/**
 * @file CXDefine.mqh
 * @brief XTA 시스템 전역 상수 및 열거형 정의
 * @last_modified 2026-05-04 10:00:00
 */

// 포인터 안전 삭제 매크로
#ifndef SAFE_DELETE
#define SAFE_DELETE(p) { if(CheckPointer(p) == POINTER_DYNAMIC) { delete p; p = NULL; } }
#endif

#ifndef SAFE_DELETE_ARRAY
#define SAFE_DELETE_ARRAY(p) { if(CheckPointer(p) == POINTER_DYNAMIC) { delete [] p; p = NULL; } }
#endif

// 포인터 및 객체 유효성 체크 매크로
#define IS_INVALID(p)   (CheckPointer(p) == POINTER_INVALID)
#define IS_VALID(p)     (CheckPointer(p) != POINTER_INVALID)
#define IS_NULL(p)      (IS_INVALID(p))

// XP (CXParam) 전용 체크
#define XP_INVALID(xp)  (IS_INVALID(xp))
#define XP_VALID(xp)    (IS_VALID(xp))

// [v5.2] 타입 안전성 강화를 위한 명시적 캐스팅 매크로
#define CX_CAST(type, obj)      dynamic_cast<type*>(obj)
#define CX_SAFE_CAST(type, obj) ((obj != NULL) ? dynamic_cast<type*>(obj) : NULL)

// [v7.14] Context 기반 서비스 획득 매크로
#define CX_GET_OBJ(ctx, type, key) CX_CAST(type, ctx.Get(key))

// 묵시적 캐스팅 금지 원칙: 모든 포인터 변환은 위 매크로 또는 명시적 타입 지정을 통해 수행할 것.

// 최상위 가드 클로저 (Guard Clauses)
#define XP_ASSERT(xp)           if(XP_INVALID(xp)) return
#define XP_ASSERT_FALSE(xp)     if(XP_INVALID(xp)) return false
#define XP_ASSERT_NULL(xp)      if(XP_INVALID(xp)) return NULL

// [v5.1] 신호 필수 가드 (필요한 경우 명시적 사용)
#define XP_SIG_ASSERT(xp)       if(XP_INVALID(xp) || IS_NULL(xp.sig_ptr)) return

// 결과 반환형 가드 (CXResult)
#define ASSERT_RESULT(p, msg)   if(IS_INVALID(p)) return CXResult::Failed(msg)

class IXLogService;
extern IXLogService* _global_log_svc;

// 로그 서비스 유효성 체크 및 전역/컨텍스트 폴백 지원
#define HAS_LOG(xp)     (XP_VALID(xp) && (IS_VALID(xp.ctx) || IS_VALID(_global_log_svc)))
#define GET_LOG(xp)     (IS_VALID(xp.ctx) ? CX_GET_OBJ(xp.ctx, IXLogService, "log") : _global_log_svc)

// [v7.2] Null Safety & Logging Standard Macros
#define XP_LOG_TRACE(xp, msg) if(IS_VALID(GET_LOG(xp))) GET_LOG(xp).Debug(xp, msg)
#define XP_LOG_INFO(xp, msg)  if(IS_VALID(GET_LOG(xp))) GET_LOG(xp).Info(xp, msg)
#define XP_LOG_DEBUG(xp, msg) if(IS_VALID(GET_LOG(xp))) GET_LOG(xp).Debug(xp, msg)
#define XP_LOG_WARN(xp, msg)  if(IS_VALID(GET_LOG(xp))) GET_LOG(xp).Warn(xp, msg)
#define XP_LOG_ERROR(xp, msg) if(IS_VALID(GET_LOG(xp))) GET_LOG(xp).Error(xp, msg)
#define XP_LOG_OK(xp, msg)    if(IS_VALID(GET_LOG(xp))) GET_LOG(xp).Ok(xp, msg)

// 로그 레벨 정의
enum ENUM_LOG_LEVEL {
    LOG_LVL_TRACE = 0,  // 가장 상세한 로그
    LOG_LVL_INFO  = 1,  // 일반 정보 로그
    LOG_LVL_DEBUG = 2,  // 디버그 로그
    LOG_LVL_WARN  = 3,  // 경고 로그
    LOG_LVL_ERROR = 4,  // 에러 로그
    LOG_LVL_OK    = 5   // 성공 완료 로그 (가장 낮은 상세도)
};

// UI 영역 정의
enum ENUM_ZONE_TYPE {
    ZONE_A = 0, // 상단 고정 (Dashboard)
    ZONE_B = 1, // 중앙 스크롤 (Logging)
    ZONE_C = 2  // 하단 고정 (Status)
};

// 청산 종류 정의 (Exit Type)
enum ENUM_CX_EXIT_TYPE {
    EXIT_NONE        = 0,   // 청산 없음
    EXIT_BY_SIGNAL   = 1,   // 청산 신호 (XTA -> XTX)
    EXIT_BY_TP       = 2,   // Take Profit 도달
    EXIT_BY_SL       = 3,   // Stop Loss 도달 (예비)
    EXIT_BY_TS       = 4,   // Trailing Stop (TS)
    EXIT_BY_GRID_SET = 5    // 그리드 셋 청산 (그룹 청산)
};

// 방향 정의 (dir)
enum ENUM_CX_DIRECTION {
    CX_DIR_NONE = 0,
    CX_DIR_BUY  = 1,
    CX_DIR_SELL = 2
};

// 주문 타입 정의 (type)
enum ENUM_CX_ORDER_TYPE {
    ORDER_LIMIT_TRAILING = 1, // 리밋 트레일링
    ORDER_LIMIT          = 2, // 리밋
    ORDER_STOP           = 3, // 스탑
    ORDER_MARKET         = 9  // 시장가
};

// [v6.1] xa_status 정의 (App/Server 처리 상태)
enum ENUM_XA_STATUS {
    XA_RAW         = 0, // 텔레그램 메시지 수신 (Raw Text)
    XA_PARSED      = 1, // 인터프리터 분석 완료
    XA_LIQUIDATION = 2, // 청산/취소 요청
    XA_WAITING     = 3, // 사용자 승인 대기 (Manual Mode)
    XA_ACCEPTED    = 4, // EA 전달 대상 (Accepted)
    XA_REVOKE_REQ  = 5, // 사용자 취소 요청
    XA_TERMINATED  = 6, // 모든 프로세스 종료 완료
    XA_DROPPED     = 9  // 필터링 또는 무시됨
};

// xe_status 정의 (XTA 전용 라이프사이클)
enum ENUM_XE_STATUS {
    XE_READY            = 0,  // 초기 상태
    XE_PENDING_PLACED   = 1,  // 대기 오더 접수 중
    XE_PENDING_VERIFIED = 2,  // 대기 오더 확인 완료 (2중 체크)
    XE_TRL_MONITORING   = 3,  // 대기 오더 트레일링 감시 시작
    XE_TRL_STARTED      = 4,  // 트레일링 시작 (스탑리밋값 전달)
    XE_TRL_PRICE_MOVED  = 5,  // 트레일링 진입가 이동
    XE_EXECUTING_MARKET = 6,  // 시장가 주문 실행 중 (체결 대기)
    XE_EXECUTED         = 10, // 체결 완료 (G0 진입)

    // [v6.0] 익절 트레일링 세분화 코드 (Entry Trailing과 분리)
    XE_IKTE_STARTED      = 15, // 익절 트레일링 시작 (TS 가동)
    XE_IKTE_PRICE_MOVED  = 16, // 익절 트레일링 가격 이동

    // [v5.3] 청산 사유별 세분화 코드 (20 ~ 29 ZONE)
    XE_CLOSED_SIGNAL    = 20, // App 신호에 의한 청산
    XE_CLOSED_TP        = 21, // Take Profit 도달 청산
    XE_CLOSED_IKTE      = 22, // 익절 트레일링(IkTe/TS) 청산
    XE_CLOSED_SL        = 23, // Stop Loss 도달 청산
    XE_CLOSED_MANUAL    = 24, // 터미널 수동 또는 외부 강제 청산

    XE_ERROR            = 99  // 에러 발생
};

// 세션 상태 (내부 관리용)
enum ENUM_SESSION_STATE {
    SESSION_READY,
    SESSION_WAITING_ENTRY,
    SESSION_PLACING,        // 초기 주문 배치 단계 (신규)
    SESSION_TRL_BOUNDARY,   // 트리거 경계값 대기 단계 (세분화)
    SESSION_TRL_ACTIVE,     // 트리거 이후 적극적 추적 단계 (세분화)
    SESSION_IK_BOUNDARY,    // 익트(TS) 수익권 진입 대기 단계 (신규)
    SESSION_IK_ACTIVE,      // 익트(TS) 수익 추적 활성 단계 (신규)
    SESSION_GRID_ACTIVE,
    SESSION_MONITOR_G0,     // G0 마스터 포지션 감시 단계
    SESSION_LIQUIDATING,
    SESSION_CLOSED,
    SESSION_ERROR = 99      // 에러 상태
};

/**
 * @brief 세션 상태 명칭 반환 도우미
 */
inline string SessionStateName(int state) {
    switch(state) {
        case SESSION_READY:         return "READY";
        case SESSION_WAITING_ENTRY: return "WAITING_ENTRY";
        case SESSION_PLACING:       return "PLACING";
        case SESSION_TRL_BOUNDARY:  return "TRL_BOUNDARY";
        case SESSION_TRL_ACTIVE:    return "TRL_ACTIVE";
        case SESSION_IK_BOUNDARY:   return "IK_BOUNDARY";
        case SESSION_IK_ACTIVE:     return "IK_ACTIVE";
        case SESSION_GRID_ACTIVE:   return "GRID_ACTIVE";
        case SESSION_MONITOR_G0:    return "MONITOR_G0";
        case SESSION_LIQUIDATING:   return "LIQUIDATING";
        case SESSION_CLOSED:        return "CLOSED";
        case SESSION_ERROR:         return "ERROR";
        default:                    return StringFormat("UNKNOWN(%d)", state);
    }
}

