/**
 * @class CXUtil
 * @brief 전역 유틸리티 함수 모음
 */
class CXUtil {
public:
    /**
     * @brief 주문 코멘트에서 GID와 GNO를 파싱함 (형식: "GID-GNO" 또는 "SID")
     */
    static void ParseOrderComment(const string comment, string &gid, int &gno) {
        gid = ""; gno = 0;
        if(comment == "") return;

        string parts[];
        if(StringSplit(comment, '-', parts) >= 4) {
            gid = StringFormat("%s-%s-%s", parts[0], parts[1], parts[2]);
            gno = (int)StringToInteger(parts[3]);
        } else {
            // 파싱 불가 시 전체를 GID로 간주 (방어 코드)
            gid = comment;
        }
    }

    /**
     * @brief SID로부터 GID를 추출함 (앞 16자)
     */
    static string GetGidFromSid(const string sid) {
        return (StringLen(sid) >= 16) ? StringSubstr(sid, 0, 16) : sid;
    }

    /**
     * @brief GID와 GNO를 조합하여 코멘트를 생성함 (형식: "GID-GNO")
     */
    static string CreateComment(const string gid, const int gno) {
        return StringFormat("%s-%02d", gid, gno);
    }

    /**
     * @brief 코멘트로부터 SID 검색용 접두사를 생성함 (형식: "GID-GNO-")
     */
    static string GetSidPrefixFromComment(const string comment) {
        string gid; int gno;
        ParseOrderComment(comment, gid, gno);
        return (gid != "") ? StringFormat("%s-%02d-", gid, gno) : "";
    }

    /**
     * @brief 다음 그리드 진입을 위한 SID 및 GID를 생성함
     */
    static bool CreateNextGridIds(const string current_sid, int cno, int next_gno, int dir, int type, string &next_sid, string &next_gid) {
        string parts[];
        if(StringSplit(current_sid, '-', parts) >= 3) {
            next_gid = StringFormat("%04d-%s-%s", cno, parts[1], parts[2]);
            next_sid = StringFormat("%s-%02d-%d-%d", next_gid, next_gno, dir, type);
            return true;
        }
        return false;
    }
};

