/**
 * @class CXSignal
 * @brief 진입(Entry) 및 청산(Exit) 신호를 모두 수용하는 통합 데이터 객체
 * @details [v5.4] Master Schema v1.0 대응 (id 필드 추가)
 */
class CXSignal : public CObject
{
public:
    //-- 기본 식별자
    int       id;           // [v5.4] Database Primary Key (Internal ID)
    string    sid;          // Signal ID (Primary Key Reference)

    //-- 공통 식별자
    int       signal;       // 1: 진입(Entry), 2: 청산(Exit)
    string    gid;          // Group ID

    //-- 계층 정보
    int       cno;          // Channel No
    int       sno;          // Signal No
    int       gno;          // Group No (0: Master, 1+: Grid)

    //-- 데이터 소스 메타
    int       msg_id;       // External Message ID
    int       raw_id;       // External Raw Signal ID

    //-- 거래 속성
    string    symbol;
    int       dir;          // 1: Buy, 2: Sell
    int       type;         // Entry/Exit Type

    //-- 가격 및 로트 정보
    double    price_signal; // 신호 발생 시점 가격
    double    price_open;   // 실제 체결 가격
    double    price_close;  // 청산 가격
    double    tp;           // 익절 포인트 (Points)
    double    sl;           // 손절 포인트 (Points)

    //-- 트레일링/그리드 파라미터
    double    limit_offset; // 진입/청산 간격
    double    te_start;     // Trailing Entry 시작
    double    te_step;      // Trailing Entry 스텝
    double    te_limit;     // Trailing Entry 한계
    int       te_interval;  // 트레일링 체크 주기
    int       ts_start;     // Trailing Stop 시작
    int       ts_step;      // Trailing Stop 스텝
    double    ikte_start;   // [v6.0] 익절 트레일링 시작
    double    ikte_step;    // [v6.0] 익절 트레일링 스텝
    double    lot;          // 주문 수량

    //-- 상태 관리
    int       xa_entry;     // [v7.7] 진입 전략 코드 (SSOT)
    int       xa_exit;      // [v7.7] 청산 전략 코드 (SSOT)
    int       xe_status;    // XTA 상태
    string    xe_status_msg;// 상세 상태 메시지

    //-- 인프라 정보
    long      ticket;       // MT5 Ticket
    long      magic;        // Magic Number
    datetime  created;      // 생성 시간
    datetime  updated;      // 최종 갱신 시간

    //-- 참조 객체 (Payload)
    CXDatabase* db;         
    CXConfig*   config;     
    CObject*    caller;     

    CXSignal() : id(0), sid(""), ticket(0), magic(0), gid(""), msg_id(0), raw_id(0),
                 cno(0), sno(0), gno(0), symbol(_Symbol), dir(0), type(1), lot(0.01),
                 price_signal(0), price_open(0), price_close(0), tp(0), sl(0),
                 limit_offset(0), te_start(0), te_step(0), te_limit(0), te_interval(0), 
                 ts_start(0), ts_step(0), ikte_start(0), ikte_step(0),
                 xa_entry(0), xa_exit(0), xe_status(0), xe_status_msg(""),
                 created(0), updated(0),
                 db(NULL), config(NULL), caller(NULL) {}

    /**
     * @brief 상태 변경 및 로깅 통합 (패턴 B)
     */
    void SetStatus(ENUM_XE_STATUS new_status, string msg = "") {
        if((ENUM_XE_STATUS)this.xe_status == new_status && msg == this.xe_status_msg) return;

        string old_status_name = EnumToString((ENUM_XE_STATUS)this.xe_status);
        this.xe_status = (int)new_status;
        this.xe_status_msg = msg;

        PrintFormat("[STATUS] SID:%s | %s -> %s | Msg: %s", 
                    sid, old_status_name, EnumToString(new_status), msg);
    }
};

