/**
 * @class CXPositionManager
 * @brief Manages open positions and exit trailing protection
 */
class CXPositionManager : public IXPositionManager {
private:
    ulong           m_ticket;
    CTrade          m_trade;
    CXExitTrailing  m_exit_trl; 

public:
    CXPositionManager() : m_ticket(0) {}
    ~CXPositionManager() {}

    /**
     * @brief 티켓으로 유효한 관리 포지션인지 즉시 확인 (패턴 A)
     */
    static bool IsActiveAndManaged(ulong ticket, long magic) {
        if(ticket <= 0 || !PositionSelectByTicket(ticket)) return false;
        return (PositionGetInteger(POSITION_MAGIC) == magic);
    }

    virtual void SetMagic(ulong magic) override { m_trade.SetExpertMagicNumber(magic); }

    virtual void Reset() override {
        m_ticket = 0;
        m_exit_trl.Reset();
    }

    /**
     * @brief 특정 포지션의 현재 수익률(Points)을 반환합니다.
     */
    virtual double GetProfitPoints(long ticket) override {
        if(ticket <= 0) return 0;
        if(!PositionSelectByTicket((ulong)ticket)) return 0;

        string symbol = PositionGetString(POSITION_SYMBOL);
        double open_p = PositionGetDouble(POSITION_PRICE_OPEN);
        double cur_p  = PositionGetDouble(POSITION_PRICE_CURRENT);
        double point  = SymbolInfoDouble(symbol, SYMBOL_POINT);
        int    dir    = (int)PositionGetInteger(POSITION_TYPE);

        double diff = (dir == POSITION_TYPE_BUY) ? (cur_p - open_p) : (open_p - cur_p);
        return (point > 0) ? (diff / point) : 0;
    }

    virtual bool Update(CXParam* xp) override {
        if(XP_INVALID(xp) || IS_NULL(xp.sig_ptr)) return false;

        // [v4.3] 포지션 부재 확인 (수동 종료 대응)
        if(!SelectPosition(xp)) {
            if(xp.sig_ptr.xe_status == XE_EXECUTED) {
                xp.sig_ptr.SetStatus(XE_CLOSED_MANUAL, "Position closed manually/externally");
                XP_LOG_INFO(xp, StringFormat("[POS-MISS] %s. Closing Session. SID:%s", xp.sig_ptr.xe_status_msg, xp.sig_ptr.sid));
                UpdateStatus(xp);
            }
            return false;
        }

        CheckAndSetInitialSLTP(xp);

        CXSignal* signal = xp.sig_ptr;
        if(signal.xe_status >= XE_EXECUTED && signal.ts_start > 0) {
            // [v5.0] Note: trade is now internal to the manager
            m_exit_trl.Process(xp);
        }

        return true;
    }

    virtual void HandleTradeTransaction(CXParam* xp) {
        if(XP_INVALID(xp) || IS_NULL(xp.sig_ptr) || !xp.has_trans) return;
        CXSignal* signal = xp.sig_ptr;

        // [v5.28] 티켓 매칭 및 청산 트랜잭션 정밀 처리
        if(xp.trans.position != m_ticket && xp.trans.position != (ulong)signal.ticket) return;

        switch(xp.trans.type) {
            case TRADE_TRANSACTION_HISTORY_ADD:
                if(m_ticket > 0 && !PositionSelectByTicket(m_ticket)) {
                    // 포지션 소멸 확인됨
                    if(signal.xe_status < XE_CLOSED_SIGNAL) {
                        signal.SetStatus(XE_CLOSED_MANUAL, "[TRANS] Position Closed (Manual/External)");
                        UpdateStatus(xp);
                    }
                }
                break;

            case TRADE_TRANSACTION_DEAL_ADD:
                if(xp.trans.deal != 0 && HistoryDealSelect(xp.trans.deal)) {
                    long entry_type = HistoryDealGetInteger(xp.trans.deal, DEAL_ENTRY);
                    if(entry_type == DEAL_ENTRY_OUT) {
                        // [v7.6] Terminal Double Check: Confirm position is really gone from active list
                        if(PositionSelectByTicket(xp.trans.position)) {
                            XP_LOG_WARN(xp, StringFormat("[TRANS-SYNC-WAIT] DEAL_OUT detected but position %lld still active. Deferring DB update.", xp.trans.position));
                            return;
                        }

                        // [v5.3] 청산 딜 발생 -> 사유별 xe_status 세분화 기록
                        signal.price_close = HistoryDealGetDouble(xp.trans.deal, DEAL_PRICE);

                        string deal_comment = HistoryDealGetString(xp.trans.deal, DEAL_COMMENT);
                        StringToLower(deal_comment);

                        if(StringFind(deal_comment, "tp") >= 0) {
                            signal.SetStatus(XE_CLOSED_TP, "[CLOSED] Take Profit Hit");
                        }
                        else if(StringFind(deal_comment, "sl") >= 0) {
                            // [v5.3] 익절 트레일링 활성 여부에 따른 코드 분기
                            if(m_exit_trl.IsActive()) {
                                signal.SetStatus(XE_CLOSED_IKTE, "[CLOSED] IkTe (Trailing Stop) Hit");
                            } else {
                                signal.SetStatus(XE_CLOSED_SL, "[CLOSED] Stop Loss Hit");
                            }
                        }
                        else {
                            if(signal.xa_exit > 0) {
                                signal.SetStatus(XE_CLOSED_SIGNAL, "[CLOSED] Exited by App Signal");
                            } else {
                                signal.SetStatus(XE_CLOSED_MANUAL, "[CLOSED] Manual or External Closure");
                            }
                        }

                        UpdateStatus(xp);
                        XP_LOG_OK(xp, StringFormat("[TRANS-CLOSE] SID:%s, Final Exit Confirmed via Transaction. XE: %d", signal.sid, signal.xe_status));
                    }
                }
                break;
        }
    }

    virtual bool SelectPosition(CXParam* xp) override {
        if(IS_INVALID(xp) || IS_NULL(xp.sig_ptr)) return false;
        CXSignal* signal = xp.sig_ptr;

        // 1. 이미 캐싱된 티켓으로 선택 시도
        if(m_ticket > 0 && PositionSelectByTicket(m_ticket)) return true;

        // 2. 신호 객체에 저장된 티켓(Position ID)으로 선택 시도
        if(signal.ticket > 0 && PositionSelectByTicket((ulong)signal.ticket)) {
            m_ticket = (ulong)signal.ticket;
            return true;
        }

        // 3. 전체 포지션 스캔 (Comment 기반)
        for(int i = PositionsTotal() - 1; i >= 0; i--) {
            ulong t = PositionGetTicket(i);
            if(PositionSelectByTicket(t)) {
                if(PositionGetString(POSITION_COMMENT) == signal.sid) {
                    m_ticket = t; 
                    signal.ticket = (long)t; 
                    return true;
                }
            }
        }
        return false;
    }

private:
    void CheckAndSetInitialSLTP(CXParam* xp) {
        if(XP_INVALID(xp) || IS_NULL(xp.sig_ptr)) return;
        CXSignal* signal = xp.sig_ptr;
        double cur_sl = PositionGetDouble(POSITION_SL);
        double cur_tp = PositionGetDouble(POSITION_TP);
        if(cur_sl != 0 || cur_tp != 0) return;

        // [v7.14] Use Context DI for direction
        IXDirection* dir_obj = NULL;
        if(XP_VALID(xp) && IS_VALID(xp.ctx)) dir_obj = CX_GET_OBJ(xp.ctx, IXDirection, "direction");
        if(IS_NULL(dir_obj)) dir_obj = CXDirectionFactory::Create(signal.dir);

        double open_price = PositionGetDouble(POSITION_PRICE_OPEN);
        double point = SymbolInfoDouble(signal.symbol, SYMBOL_POINT);
        int digits = (int)SymbolInfoInteger(signal.symbol, SYMBOL_DIGITS);
        double sl_price = 0, tp_price = 0;

        if(signal.sl > 0) sl_price = dir_obj.SubPoints(open_price, signal.sl * point);
        if(signal.tp > 0) tp_price = dir_obj.AddPoints(open_price, signal.tp * point);

        if(sl_price > 0 || tp_price > 0) {
            XP_LOG_INFO(xp, StringFormat("[POS-INIT-SLTP] Setting SL:%.5f, TP:%.5f", sl_price, tp_price));
            m_trade.PositionModify(m_ticket, NormalizeDouble(sl_price, digits), NormalizeDouble(tp_price, digits));
        }
    }

    void UpdateStatus(CXParam* xp) {
        if(XP_INVALID(xp) || IS_NULL(xp.sig_ptr)) return;

        CXDatabase* db = CX_GET_OBJ(xp.ctx, CXDatabase, "db");
        if(IS_VALID(db)) {
            CXSignalRepository repo(db);
            repo.UpdateStatus(xp.sig_ptr);
        }
    }
};
