/**
 * @class CXSignalRepository
 * @brief 신호(Signal) 데이터 액세스 전담 클래스
 */
class CXSignalRepository : public CObject {
private:
    CXDatabase* m_db;

public:
    CXSignalRepository(CXDatabase* db) : m_db(db) {}

    int FindPendingSignals(CArrayObj* entries, CArrayObj* exits) {
        if(m_db == NULL || m_db.GetHandle() == INVALID_HANDLE) return 0;
        string sql = "SELECT * FROM signals WHERE (xa_entry > 0 AND xe_status <= 1) OR (xa_exit > 0 AND xe_status < 20)";
        int req = DatabasePrepare(m_db.GetHandle(), sql);
        if(req == INVALID_HANDLE) return 0;
        int count = 0;
        while(DatabaseRead(req)) {
            CXSignal* sig = new CXSignal();
            LoadSignal(req, sig);
            if(sig.xa_entry > 0 && sig.xe_status <= 1) entries.Add(sig);
            if(sig.xa_exit > 0 && sig.xe_status < 20) exits.Add(sig);
            count++;
        }
        DatabaseFinalize(req);
        return count;
    }

    int GetActiveSignals(CArrayObj* list) {
        if(m_db == NULL || m_db.GetHandle() == INVALID_HANDLE) return 0;
        string sql = StringFormat("SELECT * FROM signals WHERE xe_status >= %d AND xe_status < %d", XE_READY, XE_CLOSED_SIGNAL);
        int req = DatabasePrepare(m_db.GetHandle(), sql);
        if(req == INVALID_HANDLE) return 0;
        int count = 0;
        while(DatabaseRead(req)) {
            CXSignal* sig = new CXSignal();
            LoadSignal(req, sig);
            list.Add(sig);
            count++;
        }
        DatabaseFinalize(req);
        return count;
    }

    bool GetBySid(const string sid, CXSignal* sig) {
        if(m_db == NULL || m_db.GetHandle() == INVALID_HANDLE || sid == "" || sig == NULL) return false;
        string sql = StringFormat("SELECT * FROM signals WHERE sid='%s'", sid);
        int req = DatabasePrepare(m_db.GetHandle(), sql);
        if(req == INVALID_HANDLE) return false;
        bool success = false;
        if(DatabaseRead(req)) { LoadSignal(req, sig); success = true; }
        DatabaseFinalize(req);
        return success;
    }

    int GetStatusBySid(const string sid) {
        if(m_db == NULL || m_db.GetHandle() == INVALID_HANDLE || sid == "") return -1;
        string sql = StringFormat("SELECT xe_status FROM signals WHERE sid='%s'", sid);
        int req = DatabasePrepare(m_db.GetHandle(), sql);
        if(req == INVALID_HANDLE) return -1;
        int status = -1;
        if(DatabaseRead(req)) DatabaseColumnInteger(req, 0, status);
        DatabaseFinalize(req);
        return status;
    }

    bool InsertSignal(CXSignal* sig) {
        if(m_db == NULL || IS_INVALID(sig)) return false;
        string sql = StringFormat(
            "INSERT OR IGNORE INTO signals (sid, gid, cno, sno, gno, xa_entry, xa_exit, xe_status, xe_status_msg, symbol, dir, lot, ticket, magic) "
            "VALUES ('%s', '%s', %d, %d, %d, %d, %d, %d, '%s', '%s', %d, %.2f, %lld, %lld)",
            sig.sid, sig.gid, sig.cno, sig.sno, sig.gno, sig.xa_entry, sig.xa_exit, sig.xe_status, sig.xe_status_msg, 
            sig.symbol, sig.dir, sig.lot, (long)sig.ticket, (long)sig.magic
        );
        return m_db.Execute(sql);
    }

    bool UpdateStatus(CXSignal* sig) {
        if(m_db == NULL || IS_INVALID(sig)) return false;
        m_db.Begin();
        string sql = StringFormat(
            "UPDATE signals SET xe_status=%d, xe_status_msg='%s', price_open=%.5f, price_close=%.5f, "
            "ticket=%lld, magic=%lld, updated=datetime('now','localtime') WHERE sid='%s'",
            sig.xe_status, sig.xe_status_msg, sig.price_open, sig.price_close, (long)sig.ticket, (long)sig.magic, sig.sid
        );
        bool res = m_db.Execute(sql);
        if(res) m_db.Commit(); else m_db.Rollback();
        return res;
    }

    int GetAllSignalsForDashboard(CArrayObj* list) {
        if(m_db == NULL || m_db.GetHandle() == INVALID_HANDLE) return 0;
        string sql = "SELECT * FROM signals ORDER BY updated DESC LIMIT 20";
        int req = DatabasePrepare(m_db.GetHandle(), sql);
        if(req == INVALID_HANDLE) return 0;
        int count = 0;
        while(DatabaseRead(req)) {
            CXSignal* sig = new CXSignal();
            LoadSignal(req, sig);
            list.Add(sig);
            count++;
        }
        DatabaseFinalize(req);
        return count;
    }

    int GetTotalSignalCount() {
        if(m_db == NULL || m_db.GetHandle() == INVALID_HANDLE) return 0;
        string sql = "SELECT COUNT(*) FROM signals";
        int req = DatabasePrepare(m_db.GetHandle(), sql);
        int count = 0;
        if(req != INVALID_HANDLE) { if(DatabaseRead(req)) DatabaseColumnInteger(req, 0, count); DatabaseFinalize(req); }
        return count;
    }

    CXSignal* FindByComment(const string comment, CArrayObj* list) {
        if(comment == "" || list == NULL) return NULL;
        string gid; int gno;
        CXUtil::ParseOrderComment(comment, gid, gno);
        for(int i = 0; i < list.Total(); i++) {
            CXSignal* sig = CX_CAST(CXSignal, list.At(i));
            if(sig != NULL && sig.gid == gid && sig.gno == gno) return sig;
        }
        return NULL;
    }

private:
    void LoadSignal(int req, CXSignal* sig) {
        sig.sid             = GetText(req, "sid");
        sig.gid             = GetText(req, "gid");
        sig.cno             = GetInt(req, "cno");
        sig.sno             = GetInt(req, "sno");
        sig.gno             = GetInt(req, "gno");
        sig.xa_entry        = GetInt(req, "xa_entry");
        sig.xa_exit         = GetInt(req, "xa_exit");
        sig.xe_status       = GetInt(req, "xe_status");
        sig.xe_status_msg   = GetText(req, "xe_status_msg");
        sig.symbol          = GetText(req, "symbol");
        sig.dir             = GetInt(req, "dir");
        sig.lot             = GetDouble(req, "lot");
        sig.ticket          = GetLong(req, "ticket");
        sig.magic           = GetLong(req, "magic");
    }

    string GetText(int req, string name) {
        int idx = GetColumnIndex(req, name);
        string val = ""; if(idx >= 0) DatabaseColumnText(req, idx, val);
        return val;
    }
    int GetInt(int req, string name) {
        int idx = GetColumnIndex(req, name);
        int val = 0; if(idx >= 0) DatabaseColumnInteger(req, idx, val);
        return val;
    }
    double GetDouble(int req, string name) {
        int idx = GetColumnIndex(req, name);
        double val = 0; if(idx >= 0) DatabaseColumnDouble(req, idx, val);
        return val;
    }
    long GetLong(int req, string name) {
        int idx = GetColumnIndex(req, name);
        long val = 0; if(idx >= 0) DatabaseColumnLong(req, idx, val);
        return val;
    }
    int GetColumnIndex(int req, string name) {
        for(int i=0; i<DatabaseColumnsCount(req); i++) {
            string n; DatabaseColumnName(req, i, n);
            if(n == name) return i;
        }
        return -1;
    }
};

