        CArrayObj* reverse_inject_queue = xp.filter_list; 

        // 1. 포지션 이벤트 처리
        if(xp.i_val1 == TE_EVENT_POSITION_CHANGE || xp.i_val1 == TE_EVENT_PERIODIC_SCAN) {
