/**
 * @class CXTradingSessionPool
 * @brief 트레이딩 세션(CXTradingSession)의 생성, 조회 및 생명주기를 관리하는 풀(Pool) 클래스
 */
class CXTradingSessionPool : public CObject {
private:
    CArrayObj     m_sessions; // 활성 세션 리스트
    IXLogService* m_log;

public:
    CXTradingSessionPool(IXLogService* log = NULL) : m_log(log) {}
    ~CXTradingSessionPool() { m_sessions.Clear(); }

    /**
     * @brief 새로운 세션을 생성하여 풀에 추가
     */
    CXTradingSession* CreateSession(IRepository* repo, ICXContext* context) {
        CXTradingSession* session = new CXTradingSession(repo, context);
        if(session != NULL) {
            m_sessions.Add(session);
        }
        return session;
    }

    /**
     * @brief 특정 조건을 만족하는 세션 조회 (예: SID 기준)
     * @details (실제 구현 시 SID 매핑 로직 추가 필요)
     */
    CXTradingSession* GetSession(int index) {
        return (CXTradingSession*)m_sessions.At(index);
    }

    /**
     * @brief 종료된 세션 정리
     */
    void PurgeClosed() {
        for(int i = m_sessions.Total() - 1; i >= 0; i--) {
            // (실제 구현 시 세션의 상태를 체크하여 제거)
            // if(GetSession(i)->IsClosed()) m_sessions.Delete(i);
        }
    }

    int Total() { return m_sessions.Total(); }
};

#endif

