//+------------------------------------------------------------------+
#ifndef CX_DATABASE_MQH
#define CX_DATABASE_MQH

#include "..\..\Domain\Common\CXDefine.mqh"
#include <Arrays\ArrayString.mqh>
#include "..\..\Domain\Common\CXConfig.mqh"
#include "..\Logging\CXLogDispatcher.mqh"

/**
 * @class CXDatabase
 * @brief 2-Layer SQLite Async Writer & Transaction Manager (Singleton)
 */
class CXDatabase : public CObject {
protected:
    int           m_db;
    string        m_full_path;

private:
    CArrayString  m_queue_high;   
    CArrayString  m_queue_normal; 
    const int     m_check_interval;

public:
    static CXDatabase* GetInstance() {
        static CXDatabase instance;
        return GetPointer(instance);
    }

    CXDatabase() : m_db(INVALID_HANDLE), m_check_interval(5), m_full_path("") {}
    ~CXDatabase() { Close(); }

    bool Open(CXParam* xp) {
        if(XP_INVALID(xp)) return false;

        int flags = DATABASE_OPEN_READWRITE;
        if(XConfig.DBUseCommon()) flags |= DATABASE_OPEN_COMMON;

        string db_name = XConfig.DBPath();
        m_db = DatabaseOpen(db_name, flags);

        string data_folder = (XConfig.DBUseCommon()) ? TerminalInfoString(TERMINAL_COMMONDATA_PATH) : TerminalInfoString(TERMINAL_DATA_PATH);
        m_full_path = data_folder + "\\MQL5\\Files\\" + db_name;

        if(m_db == INVALID_HANDLE) return false;

        DatabaseExecute(m_db, "PRAGMA journal_mode=WAL;");
        DatabaseExecute(m_db, "PRAGMA synchronous=NORMAL;");
        return true;
    }

    bool BootUp(CXParam* xp) {
        if(IS_INVALID(xp)) return false;
        IXLogService* log_svc = GET_LOG(xp);

        if(!Open(xp)) {
            if(IS_VALID(log_svc)) {
                CXParam xp_err; 
                xp_err.msg = StringFormat("Database Open Failed. Path: %s (Err: %d)", FullPath(), GetLastError());
                log_svc.Error(GetPointer(xp_err));
            }
            return false;
        }

        if(IS_VALID(log_svc)) {
            CXParam xp_path;
            xp_path.msg = "Database Connected. Path: " + FullPath();
            log_svc.Info(GetPointer(xp_path));
        }

        // [v5.0] CNO 파라미터 관리용 테이블 생성
        string sql_params = "CREATE TABLE IF NOT EXISTS cno_params ("
                            "cno INTEGER PRIMARY KEY, "
                            "limit_offset INTEGER, "
                            "te_start INTEGER, "
                            "te_step INTEGER, "
                            "ikte_start INTEGER, "
                            "ikte_step INTEGER, "
                            "last_update DATETIME DEFAULT (datetime('now','localtime')))";
        Execute(sql_params);

        // [v5.4] 상세 이력 테이블 생성
        string sql_history = "CREATE TABLE IF NOT EXISTS signal_status_history ("
                             "id            INTEGER PRIMARY KEY AUTOINCREMENT, "
                             "sid           TEXT, "
                             "gid           TEXT, "
                             "cno           INTEGER, "
                             "time          DATETIME DEFAULT CURRENT_TIMESTAMP, "
                             "price_signal  REAL, "
                             "price_open    REAL, "
                             "price_close   REAL, "
                             "tp            REAL, "
                             "sl            REAL, "
                             "ts_start      INTEGER, "
                             "ts_step       INTEGER, "
                             "msg           TEXT)";
        Execute(sql_history);
        Execute("CREATE INDEX IF NOT EXISTS idx_status_sid ON signal_status_history (sid)");

        // [v5.41] 신호 마스터 테이블 생성 (XA_ENTRY/XA_EXIT 반영)
        string sql_signals = "CREATE TABLE IF NOT EXISTS signals ("
                             "id            INTEGER PRIMARY KEY AUTOINCREMENT, "
                             "sid           TEXT UNIQUE, "
                             "gid           TEXT, "
                             "cno           INTEGER, "
                             "sno           INTEGER, "
                             "gno           INTEGER, "
                             "xa_entry      INTEGER DEFAULT 0, "
                             "xa_exit       INTEGER DEFAULT 0, "
                             "xe_status     INTEGER DEFAULT 0, "
                             "xe_status_msg TEXT, "
                             "symbol        TEXT, "
                             "dir           INTEGER, "
                             "lot           REAL, "
                             "ticket        INTEGER, "
                             "magic         INTEGER, "
                             "created       DATETIME DEFAULT (datetime('now','localtime')), "
                             "updated       DATETIME DEFAULT (datetime('now','localtime')))";
        Execute(sql_signals);
        Execute("CREATE INDEX IF NOT EXISTS idx_signals_sid ON signals (sid)");

        return true;
    }

    string FullPath() const { return m_full_path; }

    void Close() {
        if(m_db != INVALID_HANDLE) { DatabaseClose(m_db); m_db = INVALID_HANDLE; }
    }

    int GetHandle() { return m_db; }

    bool Begin()  { return DatabaseExecute(m_db, "BEGIN TRANSACTION;"); }
    bool Commit() { return DatabaseExecute(m_db, "COMMIT;"); }
    bool Rollback() { return DatabaseExecute(m_db, "ROLLBACK;"); }

    bool Execute(string sql) {
        if(m_db == INVALID_HANDLE || sql == "") return false;
        int retry_count = 0;
        while(retry_count < 10) {
            ResetLastError();
            if(DatabaseExecute(m_db, sql)) return true;
            int err = GetLastError();
            if(err == 5105 || err == 5101 || err == 5601) { 
                retry_count++;
                Sleep(50 * retry_count);
                continue;
            }
            break;
        }
        return false;
    }

    bool ExecuteBatch(CArrayString &sqls) {
        if(sqls.Total() == 0) return true;
        if(!Begin()) return false;
        for(int i = 0; i < sqls.Total(); i++) {
            if(!Execute(sqls.At(i))) { Rollback(); return false; }
        }
        return Commit();
    }

    void ProcessQueue(IXLogService* log_svc = NULL) {
        if(m_db == INVALID_HANDLE) return;
        if(m_queue_high.Total() > 0) {
            if(ExecuteBatch(m_queue_high)) m_queue_high.Clear();
        }
        int count = 0;
        while(m_queue_normal.Total() > 0 && count < m_check_interval) {
            if(Execute(m_queue_normal.At(0))) { m_queue_normal.Delete(0); count++; }
            else break;
        }
    }

    void EnqueueHigh(string sql)   { m_queue_high.Add(sql); }
    void EnqueueNormal(string sql) { m_queue_normal.Add(sql); }
};

#define XDatabase (*CXDatabase::GetInstance())

#endif

