    CTrade          m_trade;
    CXEntryTrailing m_entry_trl;

public:
    CXOrderManager() : m_ticket(0), m_sid("") {}
    ~CXOrderManager() { DeleteLines(); }

    virtual void SetMagic(ulong magic) override { m_trade.SetExpertMagicNumber(magic); }
    virtual void SetSid(string sid) override   { m_sid = sid; }

    virtual void Reset() override {
        m_ticket = 0;
        m_sid = "";
        m_entry_trl.Reset();
        DeleteLines();
    }

    /**
     * @brief 터미널 오더 선택 (SID 기반)
     */
    virtual bool SelectOrder(CXParam* xp) override {
        if(XP_INVALID(xp) || IS_NULL(xp.sig_ptr)) return false;
        CXSignal* signal = xp.sig_ptr;

        if(m_ticket > 0 && OrderSelect(m_ticket)) return true;
        if(signal.ticket > 0 && OrderSelect((ulong)signal.ticket)) {
            m_ticket = (ulong)signal.ticket;
            return true;
        }

        for(int i = OrdersTotal() - 1; i >= 0; i--) {
            ulong t = OrderGetTicket(i);
            if(OrderSelect(t)) {
                if(OrderGetString(ORDER_COMMENT) == signal.sid) {
                    m_ticket = t;
                    signal.ticket = (long)t;
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * @brief 진입 주문 실행
     */
    void ExecuteEntry(CXParam* xp) {
        XP_SIG_ASSERT(xp);
        CXSignal* signal = xp.sig_ptr;
        if(signal.xe_status != XE_READY) return;
        m_sid = signal.sid;

        // [v7.14] Context로부터 전략 객체 획득 (Interface Injection)
        IXTradingStrategy* strategy = NULL;
        if(XP_VALID(xp) && IS_VALID(xp.ctx)) strategy = CX_GET_OBJ(xp.ctx, IXTradingStrategy, "strategy");
        if(IS_VALID(strategy)) strategy.AdjustEntryParam(xp);

        // 1. 방향 객체 획득
        IXDirection* dir_obj = GetDirection(xp);

        // [v5.29] 사용자 정의 조건에 따른 진입 타입 결정 (우선순위 재정립)
        int exec_type = signal.type;

        // 1순위: 트레일링 파라미터가 있으면 무조건 트레일링 모드
        if(signal.te_start > 0) {
            exec_type = ORDER_LIMIT_TRAILING;
            XP_LOG_INFO(xp, StringFormat("[ENTRY-MODE] TRAILING Entry Mode Priority. SID:%s", m_sid));
        }
        // 2순위: 트레일링이 없고 limit_offset이 0이면 시장가
        else if(signal.limit_offset <= 0) {
            exec_type = ORDER_MARKET;
            XP_LOG_INFO(xp, StringFormat("[ENTRY-MODE] LimitOffset=0 detected (No Trailing). Forcing MARKET Entry. SID:%s", m_sid));
        }
        // 3순위: 그 외에는 고정 리밋
        else {
            exec_type = ORDER_LIMIT;
            XP_LOG_INFO(xp, StringFormat("[ENTRY-MODE] Fixed LIMIT Entry Mode. SID:%s", m_sid));
        }

        XP_LOG_INFO(xp, StringFormat("[EXEC-ENTRY-START] SID:%s, Dir:%s, Type:%d, Lot:%.2f", m_sid, dir_obj.Name(), exec_type, signal.lot));


        // 2. 진입 제약 조건 검증
        CXEntryConstraintSpec spec;
        if(!spec.IsSatisfiedBy(xp)) {
            signal.SetStatus(XE_ERROR, "[REJECT] Entry Constraints Not Satisfied");
            UpdateStatus(xp);
            XP_LOG_ERROR(xp, StringFormat("[EXEC-ENTRY-REJECT] SID:%s, Msg:%s", m_sid, signal.xe_status_msg));
            return;
        }

        XP_LOG_DEBUG(xp, StringFormat("[EXEC-ENTRY-SPEC-OK] SID:%s. Creating Executor...", m_sid));

        // 3. 전략 실행기 생성
        IXOrderExecutor* executor = CXOrderExecutorFactory::Create(exec_type);
        if(IS_NULL(executor)) {
            CX_HANDLE_ERROR(xp, StringFormat("Invalid Order Type: %d", signal.type));
            return;
        }

        // 4. 실행
        XP_LOG_DEBUG(xp, StringFormat("[EXEC-ENTRY-SENDING] SID:%s. Sending Order...", m_sid));
        bool res = executor.Execute(xp, GetPointer(m_trade), dir_obj);
        SAFE_DELETE(executor);

        if(!res) {
            CX_HANDLE_ERROR(xp, StringFormat("Execution Failed. RetCode: %d, Msg: %s", 
                                         m_trade.ResultRetcode(), m_trade.ResultRetcodeDescription()));
            return;
        }

        // 5. 성공 처리
        m_ticket = (ulong)signal.ticket;
        signal.SetStatus((ENUM_XE_STATUS)signal.xe_status, StringFormat("[INIT] Order %lld Placed", m_ticket));
        UpdateStatus(xp);
    }

    void Process(CXParam* xp) {
        if(XP_INVALID(xp) || IS_NULL(xp.sig_ptr)) return;
        CXSignal* sig = xp.sig_ptr;

        // [v4.4] 시장가 전환 대기 중이 아닐 때만 트레일링 처리
        if(sig.xe_status >= XE_PENDING_PLACED && sig.xe_status < XE_EXECUTING_MARKET) {
            if(sig.type == ORDER_LIMIT_TRAILING) {
                xp.ticket = (long)m_ticket;
                xp.trade = GetPointer(m_trade);
                if(m_entry_trl.Process(xp)) ExecuteMarketConversion(xp);
            }
        }

        if(XConfig.DrawLines() && sig.xe_status < XE_EXECUTED) DrawLines(xp);
        else DeleteLines();
    }

    void HandleTradeTransaction(CXParam* xp) {
        if(XP_INVALID(xp) || IS_NULL(xp.sig_ptr) || !xp.has_trans) return;
        CXSignal* sig = xp.sig_ptr;

        if(xp.trans.order != m_ticket && xp.trans.position != (ulong)sig.ticket) return;

        switch(xp.trans.type) {
            case TRADE_TRANSACTION_ORDER_ADD:
                if(sig.xe_status < XE_PENDING_PLACED) { 
                    sig.SetStatus(XE_PENDING_PLACED, "Order Added to Terminal");
                    UpdateStatus(xp); 
                }
                break;

            case TRADE_TRANSACTION_HISTORY_ADD:
                if(xp.trans.order != 0 && HistoryOrderSelect(xp.trans.order)) {
                    long state = HistoryOrderGetInteger(xp.trans.order, ORDER_STATE);
                    if(state == ORDER_STATE_FILLED) {
                        // [v7.6] Terminal Double Check: Confirm order is gone from active list
                        if(OrderSelect(xp.trans.order)) {
                            XP_LOG_WARN(xp, StringFormat("[TRANS-SYNC-WAIT] ORDER_FILLED detected but order %lld still in active list. Deferring DB update.", xp.trans.order));
                            return;
                        }

                        sig.ticket = HistoryOrderGetInteger(xp.trans.order, ORDER_POSITION_ID);

                        // [v5.22] 실제 체결가 및 매직 넘버 정밀 동기화
                        if(PositionSelectByTicket((ulong)sig.ticket)) {
                            sig.price_open = PositionGetDouble(POSITION_PRICE_OPEN);
                            sig.magic = PositionGetInteger(POSITION_MAGIC);
                            sig.SetStatus(XE_EXECUTED, StringFormat("[EXECUTED] Filled at %.5f (Tkt:%lld)", sig.price_open, sig.ticket));
                        } else {
                            sig.SetStatus(XE_EXECUTED, "Filled (Position selected failed)");
                        }

                        UpdateStatus(xp);
                        XP_LOG_INFO(xp, StringFormat("[TRANS-EXEC] SID:%s, PosID:%lld Confirmed at %.5f", sig.sid, sig.ticket, sig.price_open));
                    }
                    else if(state == ORDER_STATE_CANCELED || state == ORDER_STATE_EXPIRED) {
                        // [v7.6] Order Canceled or Expired
                        if(OrderSelect(xp.trans.order)) return; // Double check

                        if(sig.xe_status < XE_CLOSED_SIGNAL) {
                            sig.SetStatus(XE_CLOSED_SIGNAL, StringFormat("[CLOSED] Order %s", (state == ORDER_STATE_CANCELED ? "Canceled" : "Expired")));
                            UpdateStatus(xp);
                            XP_LOG_INFO(xp, StringFormat("[TRANS-CANCEL] SID:%s, Order %lld %s", sig.sid, xp.trans.order, (state == ORDER_STATE_CANCELED ? "Canceled" : "Expired")));
                        }
                    }
                }
                break;
        }
    }

private:
    void ExecuteMarketConversion(CXParam* xp) {
        XP_ASSERT(xp);
        CXSignal* sig = xp.sig_ptr;

        // [v4.3] 레이스 컨디션 방지: 삭제 전 주문 상태 재확인
        if(!OrderSelect(m_ticket)) {
            // 주문이 이미 사라졌다면 체결 여부 확인
            if(HistoryOrderSelect(m_ticket)) {
                if(HistoryOrderGetInteger(m_ticket, ORDER_STATE) == ORDER_STATE_FILLED) {
                    XP_LOG_INFO(xp, StringFormat("[CONV-RACE] Limit Order %lld already filled. Skipping market order. SID:%s", m_ticket, sig.sid));
                    sig.SetStatus(XE_EXECUTED, "Filled during conversion race");
                    UpdateStatus(xp);
                    return;
                }
            }
            CX_WARN(xp, StringFormat("Order %lld not found and not filled.", m_ticket));
            return;
        }

        IXDirection* dir_obj = GetDirection(xp);
        double vol = OrderGetDouble(ORDER_VOLUME_INITIAL);

        // [v7.12] Anti-Invalid Stops: Send Market Order with 0 SL/TP. 
        // CXPositionManager will set correct stops based on actual execution price in the next sync.
        double sl  = 0;
        double tp  = 0;

        // 1. 기존 오더 삭제
        if(!m_trade.OrderDelete(m_ticket)) {
            CX_WARN(xp, StringFormat("OrderDelete %lld Failed. Will retry conversion. Ret: %d", m_ticket, m_trade.ResultRetcode()));
            return;
        }

        XP_LOG_INFO(xp, StringFormat("[CONV-DEL] Limit Order %lld deleted.", m_ticket));

        // 2. 시장가 주문 실행
        bool res = dir_obj.IsBuy() ? m_trade.Buy(vol, sig.symbol, 0, sl, tp, sig.sid) 
                                   : m_trade.Sell(vol, sig.symbol, 0, sl, tp, sig.sid);
        if(!res) {
            // [v7.13] Entry Failure Recovery: Reset to XE_READY to allow retry from MasterPlacing
            CX_WARN(xp, StringFormat("Market Order Failed. Ret: %d. Resetting to XE_READY for full entry retry.", m_trade.ResultRetcode()));
            sig.SetStatus(XE_READY, "Market conversion failed, resetting for retry");
            UpdateStatus(xp);
            return;
        }

        // 3. 성공 처리
        m_ticket = m_trade.ResultOrder();
        sig.ticket = 0; 
        sig.SetStatus(XE_EXECUTING_MARKET, "Market Order Sent (Conversion)");
        UpdateStatus(xp);

        XP_LOG_INFO(xp, StringFormat("[CONV-OK] Market Order Sent. New Tkt: %lld", m_ticket));
    }

    IXDirection* GetDirection(CXParam* xp) {
        IXDirection* dir = NULL;
        if(XP_VALID(xp) && IS_VALID(xp.ctx)) dir = CX_GET_OBJ(xp.ctx, IXDirection, "direction");
        if(IS_NULL(dir) && XP_VALID(xp) && IS_VALID(xp.sig_ptr)) dir = CXDirectionFactory::Create(xp.sig_ptr.dir);
        return dir;
    }

    bool UpdateStatus(CXParam* xp) {
        if(XP_INVALID(xp) || IS_NULL(xp.sig_ptr)) return false;

        CXDatabase* db = CX_GET_OBJ(xp.ctx, CXDatabase, "db");
        if(IS_INVALID(db)) return false;

        CXSignalRepository repo(db);
        return repo.UpdateStatus(xp.sig_ptr);
    }

    void DrawLines(CXParam* xp) {
        if(XP_INVALID(xp) || IS_NULL(xp.sig_ptr) || !OrderSelect(m_ticket)) return;

        IXDirection* dir_obj = GetDirection(xp);
        if(IS_NULL(dir_obj)) return;

        double op = OrderGetDouble(ORDER_PRICE_OPEN), tp = m_entry_trl.TriggerPrice();
        string nt = "XTA_TE_TGT_" + xp.sig_ptr.sid, nr = "XTA_TE_TRG_" + xp.sig_ptr.sid;
        color  lc = dir_obj.IsBuy() ? clrBlue : clrLightPink;
        ObjectCreate(0, nt, OBJ_HLINE, 0, 0, op); ObjectSetInteger(0, nt, OBJPROP_COLOR, lc);
        ObjectCreate(0, nr, OBJ_HLINE, 0, 0, tp); ObjectSetInteger(0, nr, OBJPROP_COLOR, lc); ObjectSetInteger(0, nr, OBJPROP_STYLE, STYLE_DOT);
    }

    void DeleteLines() {
        if(m_sid != "") { ObjectDelete(0, "XTA_TE_TGT_" + m_sid); ObjectDelete(0, "XTA_TE_TRG_" + m_sid); ChartRedraw(0); }
    }
};
#endif

