#include "..\..\Interfaces\ICXContext.mqh"
#include "..\..\Interfaces\ICXParam.mqh"
#include "..\..\Interfaces\CXDefine.mqh"
#include "..\..\Interfaces\CXMacros.mqh"

/**
 * @class CXEntryManager
 * @brief 신규 진입 전략 및 파라미터 조정 담당 (Sandboxed)
 */
class CXEntryManager {
private:
    ICXContext* m_ctx;

public:
    CXEntryManager(ICXContext* ctx) : m_ctx(ctx) {}
    ~CXEntryManager() {}

    /**
     * @brief 진입 전 파라미터 최적화 및 전략 결정
     */
    void PrepareEntry(ICXParam* xp) {
        if(m_ctx == NULL || xp == NULL) return;

        ICXSignal* signal = xp.GetSignal();
        if(signal == NULL) return;

        // 진입 전 런타임 설정 조정 로직 (Adaptive Entry)
        XP_LOG_INFO(xp, StringFormat("[SANDBOX-ENTRY] Preparing Entry for SID: %s", signal.sid));
    }
};

#endif

