                        if(IS_VALID(m_log)) {
                            CXParam xl; xl.sid = xp.sid; xl.log_svc = m_log;
                            XP_LOG_WARN(GetPointer(xl), StringFormat("[RECONCILE] Position for closed SID: %s. Forcing Close.", xp.sid));
                        }
                        ClosePosition((ulong)xp.ticket, xp.magic);
                    }
                    else {
                        if(IS_VALID(reverse_inject_queue)) {
                            CXTerminalEvent* rev_ev = new CXTerminalEvent((ENUM_TERMINAL_EVENT_TYPE)xp.i_val1, (ulong)xp.ticket, xp.sid, xp.magic);
                            reverse_inject_queue.Add(rev_ev);
                        }
                    }
                }
            }
        }

        // 2. 대기 오더 이벤트 처리
        if(xp.i_val1 == TE_EVENT_ORDER_CHANGE || xp.i_val1 == TE_EVENT_PERIODIC_SCAN) {
            if(OrderSelect((ulong)xp.ticket)) {
                if(!IsManaged(xp.magic, xp.filter_magics)) return;

                if(xp.sid == "") return;

                CXSignal* sig = repo.FindByComment(xp.sid, db_signals);
                if(sig == NULL) {
                    int db_status = repo.GetStatusBySid(xp.sid);
                    // DB에 없거나 아직 로드되지 않은 경우 역주입 대상
                    if(db_status == -1 || db_status < XE_PENDING_PLACED) {
                        if(reverse_inject_queue != NULL) {
                            CXTerminalEvent* rev_ev = new CXTerminalEvent((ENUM_TERMINAL_EVENT_TYPE)xp.i_val1, (ulong)xp.ticket, xp.sid, xp.magic);
                            reverse_inject_queue.Add(rev_ev);
                        }
                    }
                }
            }
        }
    }

    bool IsManaged(long mgc, CArrayInt* managed_magics) {
        if(managed_magics == NULL) return false;
        for(int i=0; i<managed_magics.Total(); i++) if(managed_magics.At(i) == mgc) return true;
        return false;
    }

    void ClosePosition(ulong ticket, long magic) {
        CTrade trade; trade.SetExpertMagicNumber(magic);
        trade.PositionClose(ticket);
    }

    void CheckExternalClose(CXSignal* sig, CXSignalRepository &repo) {
        if(sig.xe_status >= XE_EXECUTED) {
            if(!PositionSelectByTicket((ulong)sig.ticket)) {
                // If position is gone but status is active (e.g. XE_EXECUTED, XE_IKTE_STARTED), mark as manually closed
                if(sig.xe_status == XE_EXECUTED || sig.xe_status == XE_IKTE_STARTED || sig.xe_status == XE_IKTE_PRICE_MOVED) {
                    sig.SetStatus(XE_CLOSED_MANUAL, "[CLOSED-EXT] Position Disappeared");
                }
                else if(sig.xe_status == XE_EXECUTING_MARKET) return; 

                if(HistorySelectByPosition((ulong)sig.ticket)) {
                    int deals = HistoryDealsTotal();
                    for(int k=deals-1; k>=0; k--) {
                        ulong deal_ticket = HistoryDealGetTicket(k);
                        if(HistoryDealGetInteger(deal_ticket, DEAL_ENTRY) == DEAL_ENTRY_OUT) {
                            sig.price_close = HistoryDealGetDouble(deal_ticket, DEAL_PRICE);
                            string reason = HistoryDealGetString(deal_ticket, DEAL_COMMENT);
                            if(StringFind(reason, "tp") >= 0) sig.SetStatus(XE_CLOSED_TP, "[CLOSED-EXT] Take Profit Hit");
                            else if(StringFind(reason, "sl") >= 0) sig.SetStatus(XE_CLOSED_SL, "[CLOSED-EXT] Stop Loss Hit");
                            break;
                        }
                    }
                }
                repo.UpdateStatus(sig);
            }
        }
    }
    };
    #endif

