#ifndef CX_DEFINE_MQH
#define CX_DEFINE_MQH

/**
 * @file CXDefine.mqh
 * @brief XTA 시스템 전역 상수 및 열거형 정의 (Constants & Enums)
 * @details 상태 코드, 타입 정의, 고정값 등 정적 데이터 정의 모음
 */

//--- 로그 레벨 정의
enum ENUM_LOG_LEVEL {
    LOG_LVL_TRACE = 0,
    LOG_LVL_INFO  = 1,
    LOG_LVL_DEBUG = 2,
    LOG_LVL_WARN  = 3,
    LOG_LVL_ERROR = 4,
    LOG_LVL_OK    = 5
};

//--- 방향 정의 (dir)
enum ENUM_CX_DIRECTION {
    CX_DIR_NONE = 0,
    CX_DIR_BUY  = 1,
    CX_DIR_SELL = 2
};

//--- 주문 타입 정의
enum ENUM_CX_ORDER_TYPE {
    ORDER_LIMIT_TRAILING = 1,
    ORDER_LIMIT          = 2,
    ORDER_STOP           = 3,
    ORDER_MARKET         = 9
};

//--- XA_STATUS (App/Server 처리 상태)
enum ENUM_XA_STATUS {
    XA_RAW         = 0,
    XA_PARSED      = 1,
    XA_LIQUIDATION = 2,
    XA_WAITING     = 3,
    XA_ACCEPTED    = 4,
    XA_REVOKE_REQ  = 5,
    XA_TERMINATED  = 6,
    XA_DROPPED     = 9
};

//--- XE_STATUS (EA 실행 상태)
enum ENUM_XE_STATUS {
    XE_READY            = 0,
    XE_PENDING_PLACED   = 1,
    XE_EXECUTED         = 10,
    XE_CLOSED_SIGNAL    = 20,
    XE_CLOSED_TP        = 21,
    XE_CLOSED_SL        = 23,
    XE_CLOSED_MANUAL    = 24,
    XE_ERROR            = 99
};

//--- 세션 상태 정의
enum ENUM_SESSION_STATE {
    SESSION_READY,
    SESSION_ACTIVE,
    SESSION_LIQUIDATING,
    SESSION_CLOSED,
    SESSION_ERROR = 99
};

#endif

