//|                                  Copyright 2026, Gemini CLI      |
//| [v7.8] Lightweight Sequence Orchestrator (Plan D)                |
//+------------------------------------------------------------------+
#ifndef CX_FLUENT_SEQUENCE_MQH
#define CX_FLUENT_SEQUENCE_MQH

#include "IXStep.mqh"
#include <Arrays\ArrayObj.mqh>

/**
 * @class CXFluentSequence (Now operating as LightSequence)
 * @brief O(1) 상태 매핑을 제공하는 초경량 시퀀스 엔진 (ICE 회피 설계)
 */
class CXFluentSequence : public CObject {
private:
    CXContext*                      m_ctx;
    int                             m_current_state;
    CArrayObj                       m_steps; // Holds IXStep*
    int                             m_max_state;
    string                          m_name;
    string                          m_storage_key;
    bool                            m_use_persistence;

public:
    CXFluentSequence(CXContext* ctx, string name, bool use_save = true, int max_state = 128) 
        : m_ctx(ctx), m_name(name), m_use_persistence(use_save),
          m_current_state(-1), m_max_state(max_state) {

        m_storage_key = "XFSEQ_" + name + "_" + _Symbol;

        m_steps.FreeMode(true); // Free the steps when array is cleared
        for(int i = 0; i <= m_max_state; i++) m_steps.Add(NULL);

        if(m_use_persistence && GlobalVariableCheck(m_storage_key)) {
            m_current_state = (int)GlobalVariableGet(m_storage_key);
        }
    }

    ~CXFluentSequence() {
        m_steps.Clear();
    }

    static CXFluentSequence* Create(CXContext* ctx, string name, bool use_save = true) {
        return new CXFluentSequence(ctx, name, use_save);
    }

    /**
     * @brief 스텝 등록 (1:1 상태 매핑)
     */
    void AddStep(int state_id, IXStep* step) {
        if(state_id < 0 || state_id > m_max_state || step == NULL) return;
        m_steps.Update(state_id, step);
    }

    void EnableSnapshot(string path="") {} // No-op for interface compatibility

    void Build() {
        TriggerOnEnter(m_current_state);
    }

    void Pulse(CXParam* xp) {
        if(m_current_state < 0 || m_current_state > m_max_state) return;

        IXStep* step = (IXStep*)m_steps.At(m_current_state);
        if(step == NULL) {
            if(m_current_state != SESSION_CLOSED && m_current_state != SESSION_ERROR) {
                IXLogService* log_svc = GET_LOG(xp);
                if(IS_VALID(log_svc)) log_svc.Error(xp, StringFormat("[XFSEQ-DEADEND] State %d has no step defined!", m_current_state));
                UpdateState(SESSION_ERROR);
            }
            return;
        }

        if(step.OnCondition(xp, m_ctx, m_current_state)) {
            XP_LOG_TRACE(xp, StringFormat("[SEQ-STEP] Executing %s in state %s", step.Name(), SessionStateName(m_current_state)));

            int next_state = step.OnProcess(xp, m_ctx);

            if(next_state != m_current_state && next_state != -1) {
                UpdateState(next_state);
            }
        }
    }

    int State() const { return m_current_state; }

    void ForceState(int next_state) {
        UpdateState(next_state);
    }

private:
    void UpdateState(int new_state) {
        if(m_current_state == new_state) return;
        TriggerOnExit(m_current_state);
        m_current_state = new_state;
        if(m_use_persistence) GlobalVariableSet(m_storage_key, (double)m_current_state);
        TriggerOnEnter(m_current_state);
    }

    void TriggerOnEnter(int state) {
        if(state >= 0 && state <= m_max_state) {
            IXStep* step = (IXStep*)m_steps.At(state);
            if(step != NULL) step.OnEnter(m_ctx);
        }
    }

    void TriggerOnExit(int state) {
        if(state >= 0 && state <= m_max_state) {
            IXStep* step = (IXStep*)m_steps.At(state);
            if(step != NULL) step.OnExit(m_ctx);
        }
    }
};
#endif

