        CXStepNode* node = NULL;
        if(m_map.TryGetValue(state, node) && node != NULL) node.step.OnEnter(m_ctx);
    }

    void TriggerOnExit(int state) {
        CXStepNode* node = NULL;
        if(m_map.TryGetValue(state, node) && node != NULL) node.step.OnExit(m_ctx);
