#ifndef CXAPPSERVICE_MQH
#define CXAPPSERVICE_MQH

#include "..\Interfaces\ICXAppService.mqh"
#include "..\Interfaces\ICXConfig.mqh"
#include "..\Infra\CXDatabase.mqh"
#include "..\Module\CXSignalWatcher.mqh"
#include "..\Session\CXTradingSession.mqh"

#include "CXTradingSessionPool.mqh"

class CXAppService : public ICXAppService {
private:
    ICXConfig*            m_config;
    CXDatabase*           m_db;
    CXSignalWatcher*      m_watcher;
    CXTradingSessionPool* m_sessionPool;
    ICXContext*           m_globalContext;

public:
    CXAppService(ICXConfig* config, int poolSize = 50) : m_config(config) {
        m_db = new CXDatabase();
        if(IS_INVALID(m_db)) return;

        m_watcher = new CXSignalWatcher(m_db, m_config);
        if(IS_INVALID(m_watcher)) return;

        m_sessionPool = new CXTradingSessionPool(poolSize);
        if(IS_INVALID(m_sessionPool)) return;

        m_globalContext = new CXContext();
        if(IS_INVALID(m_globalContext)) return;

        // 초기 기동 시 샌드박스 세션 일괄 생성
        m_sessionPool.Initialize(m_db, m_globalContext);
    }
    ~CXAppService() {
        SAFE_DELETE(m_db);
        SAFE_DELETE(m_watcher);
        SAFE_DELETE(m_sessionPool);
        SAFE_DELETE(m_globalContext);
    }

    //-- 세션 제어 API
    CXTradingSession* StartSession(ICXParam* param) {
        // 전역 컨텍스트와 파라미터를 조합하여 세션 시작
        return m_sessionPool.CreateSession(m_db, m_globalContext);
    }
};

#endif

