/**
 * @class CXDatabase
 * @brief 샌드박스화된 세션 전용 SQLite 핸들러
 * @details Singleton 패턴을 제거하고 세션별 독립 인스턴스로 동작하도록 구현
 */
class CXDatabase : public IRepository {
private:
    int     m_db;
    string  m_db_path;

public:
    CXDatabase() : m_db(INVALID_HANDLE), m_db_path("XTX.db") {}
    ~CXDatabase() { Close(); }

    bool Open() {
        m_db = DatabaseOpen(m_db_path, DATABASE_OPEN_READWRITE | DATABASE_OPEN_COMMON);
        if(m_db == INVALID_HANDLE) return false;

        DatabaseExecute(m_db, "PRAGMA journal_mode=WAL;");
        DatabaseExecute(m_db, "PRAGMA synchronous=NORMAL;");
        return true;
    }

    void Close() {
        if(m_db != INVALID_HANDLE) {
            DatabaseClose(m_db);
            m_db = INVALID_HANDLE;
        }
    }

    bool Execute(string sql) {
        if(m_db == INVALID_HANDLE) return false;
        return DatabaseExecute(m_db, sql);
    }

    virtual void SaveSignal(ICXSignal* signal) override {
        // CXSignalRepository에서 구체적인 SQL 실행을 위임받음
    }

    virtual void LoadParam(ICXParam* param) override {
        // 파라미터 로드 로직
    }

    int GetHandle() { return m_db; }
};

