#ifndef CXFILELOGGER_MQH
#define CXFILELOGGER_MQH

#include "..\Interfaces\ICXLogger.mqh"

/**
 * @class CXFileLogger
 * @brief 세션별 독립 로그 파일 생성 및 기록 담당
 */
class CXFileLogger : public ICXLogger {
private:
    int    m_handle;
    string m_filename;
    bool   m_enabled;

public:
    CXFileLogger() : m_handle(INVALID_HANDLE), m_enabled(true) {}
    ~CXFileLogger() { Close(); }

    /**
     * @brief {sid}-{yymmdd-hhmmss}.log 형식으로 파일 초기화
     */
    bool Init(string sid) {
        Close();
        string timestamp = TimeToString(TimeCurrent(), TIME_DATE|TIME_MINUTES|TIME_SECONDS);
        StringReplace(timestamp, ".", "");
        StringReplace(timestamp, ":", "");
        StringReplace(timestamp, " ", "-");

        m_filename = StringFormat("XTX\\%s-%s.log", sid, timestamp);
        m_handle = FileOpen(m_filename, FILE_WRITE|FILE_TXT|FILE_SHARE_READ|FILE_ANSI|FILE_COMMON);

        return (m_handle != INVALID_HANDLE);
    }

    virtual void Log(ENUM_LOG_LEVEL level, string msg) override {
        if(m_handle == INVALID_HANDLE || !m_enabled) return;
        string line = StringFormat("[%s] [%s] %s\n", EnumToString(level), TimeToString(TimeCurrent(), TIME_SECONDS), msg);
        FileWriteString(m_handle, line);
        FileFlush(m_handle);
    }

    virtual void SetEnabled(bool enabled) override { m_enabled = enabled; }
    virtual bool IsEnabled() const override { return m_enabled; }

    void Close() {
        if(m_handle != INVALID_HANDLE) {
            FileClose(m_handle);
            m_handle = INVALID_HANDLE;
        }
    }
};

#endif

