 * @brief 체결된 포지션의 실시간 상태 감시 및 TP/SL 체크 (IXStep 구현)
 */
class CXStepMonitor : public IXStep {
private:
    string m_name;

public:
    CXStepMonitor() : m_name("Step_Monitor") {}
    virtual ~CXStepMonitor() {}

    virtual string Name() override { return m_name; }

    /**
     * @brief 감시 조건 확인 (포지션이 살아있는 상태)
     */
    virtual bool OnCondition(ICXParam* xp, ICXContext* ctx, int current_state) override {
        ICXSignal* sig = xp.GetSignal();
        if(IS_INVALID(sig)) return false;

        CXSignal* signal = dynamic_cast<CXSignal*>(sig);
        return (signal.xe_status >= 10 && signal.xe_status < 20);
    }

    /**
     * @brief 실시간 모니터링 실행
     */
    virtual int OnProcess(ICXParam* xp, ICXContext* ctx) override {
        CXSignal* sig = dynamic_cast<CXSignal*>(xp.GetSignal());
        if(IS_INVALID(sig)) return -1;

        // 1. 외부 청산 명령 확인 (xa_exit > 0 일 경우 즉시 청산 시퀀스 진입)
        if(sig.xa_exit > 0) {
            XP_LOG_INFO(xp, "[STEP-MONITOR] Exit Command Detected (xa_exit > 0). Moving to LIQUIDATING.");
            return SESSION_LIQUIDATING;
        }

        // 2. 매니저를 통한 포지션 감시 및 사후 관리
        CXPositionManager* posMgr = (CXPositionManager*)ctx.Get("pos_mgr");
        if(IS_VALID(posMgr)) {
            posMgr.Update(xp);
            // 자체 청산 조건(TP/SL) 도달 시 로직 추가 가능
        }
        return -1; // 상태 유지
    }

    virtual void OnEnter(ICXContext* ctx) override {
        XP_LOG_INFO(NULL, "[STEP-MONITOR] Starting Position Monitoring");
    }

    virtual void OnExit(ICXContext* ctx) override {
        XP_LOG_INFO(NULL, "[STEP-MONITOR] Stopping Position Monitoring");
    }
};

#endif

