                            if(StringFind(reason, "tp") >= 0) sig.SetStatus(XE_CLOSED_TP, "[CLOSED-EXT] Take Profit Hit");
                            else if(StringFind(reason, "sl") >= 0) sig.SetStatus(XE_CLOSED_SL, "[CLOSED-EXT] Stop Loss Hit");
                            break;
                        }
                    }
                }
                repo.UpdateStatus(sig);
            }
        }
    }
    };
