#ifndef CXTRADINGSESSIONPOOL_MQH
#define CXTRADINGSESSIONPOOL_MQH

#include <Arrays\ArrayObj.mqh>
#include "..\Session\CXTradingSession.mqh"
#include "..\Interfaces\IXLogService.mqh"

/**
 * @class CXTradingSessionPool
 * @brief Sandboxed 세션들을 미리 생성하고 관리하는 풀 클래스
 */
class CXTradingSessionPool : public CObject {
private:
    CArrayObj     m_pool;      // 사용 가능한 유휴 세션 풀
    CArrayObj     m_active;    // 현재 사용 중인 세션 리스트
    int           m_initialCount;

public:
    CXTradingSessionPool(int count) : m_initialCount(count) {}
    ~CXTradingSessionPool() {
        m_pool.Clear();
        m_active.Clear();
    }

    /**
     * @brief EA 초기화 시 지정된 개수만큼 샌드박스 세션을 미리 생성 (Warm-up)
     */
    void Initialize(IRepository* globalRepo, ICXContext* globalContext) {
        for(int i = 0; i < m_initialCount; i++) {
            // 각 세션은 고유한 자원(DB, Log 등)을 가질 수 있도록 팩토리를 통해 생성 권장
            CXTradingSession* session = new CXTradingSession(globalRepo, globalContext);
            m_pool.Add(session);
        }
    }

    /**
     * @brief 풀에서 유휴 세션을 획득 (Borrow)
     */
    CXTradingSession* BorrowSession() {
        if(m_pool.Total() <= 0) return NULL; // 또는 추가 생성 로직

        CXTradingSession* session = (CXTradingSession*)m_pool.Detach(0);
        m_active.Add(session);
        return session;
    }

    /**
     * @brief 사용이 끝난 세션을 풀로 반환 (Return)
     */
    void ReturnSession(CXTradingSession* session) {
        for(int i = 0; i < m_active.Total(); i++) {
            if(m_active.At(i) == session) {
                m_active.Detach(i);
                session->Reset(); // 상태 초기화 후 반환
                m_pool.Add(session);
                break;
            }
        }
    }
};

#endif

