#include "..\Interfaces\IRepository.mqh"
#include "..\Models\CXSignal.mqh"
#include "CXDatabase.mqh"

class CXSignalRepository : public IRepository {
private:
    CXDatabase* m_db;

public:
    CXSignalRepository(CXDatabase* db) : m_db(db) {}
    ~CXSignalRepository() {}

    virtual void SaveSignal(ICXSignal* signal) override {
        CXSignal* sig = dynamic_cast<CXSignal*>(signal);
        if(sig == NULL || m_db == NULL) return;

        //-- 신규 규격에 따른 UPSERT 로직 (xa_entry, xa_exit 포함)
        string sql = StringFormat(
            "INSERT OR REPLACE INTO signals (sid, gid, cno, sno, gno, symbol, dir, type, lot, xa_entry, xa_exit, xe_status) "
            "VALUES ('%s', '%s', %d, %d, %d, '%s', %d, %d, %.2f, %d, %d, %d)",
            sig.sid, sig.gid, sig.cno, sig.sno, sig.gno, sig.symbol, sig.dir, sig.type, sig.lot, sig.xa_entry, sig.xa_exit, sig.xe_status
        );
        m_db.Execute(sql);
    }

    virtual void LoadParam(ICXParam* param) override {
        //-- 비즈니스 로직에 따른 파라미터 로드 구현 예정
    }

    /**
     * @brief 활성 신호 목록 조회 (xa_status & xe_status 조합 기반)
     */
    int GetActiveSignals(CArrayObj* list) {
        if(m_db == NULL) return 0;
        // spec.md: Active if xe_status < 20 AND xa_status != 6
        string sql = "SELECT * FROM signals WHERE xe_status < 20 AND xa_status != 6";
        // ... (DatabaseRead 및 LoadSignal 로직 포팅 예정)
        return 0;
    }
};

#endif

