//+------------------------------------------------------------------+
//|                                              CXExitManager.mqh   |
//|                                  Copyright 2026, Gemini CLI      |
//| [v7.4] Linear Exit Pipeline & Liquidation (DI Implementation)    |
//+------------------------------------------------------------------+
#ifndef CX_EXIT_MANAGER_MQH
#define CX_EXIT_MANAGER_MQH

#include "..\..\Domain\Common\CXParam.mqh"
#include "..\..\Domain\Common\CXDefine.mqh"
#include "..\..\Domain\Common\CXSignal.mqh"
#include "..\..\Infra\Database\CXDatabase.mqh"
#include "..\..\Infra\Database\CXSignalRepository.mqh"
#include <Trade\Trade.mqh>
#include <Arrays\ArrayLong.mqh>

#include "IXExitManager.mqh"

/**
 * @class CXExitManager
 * @brief App 청산 신호 전용의 단순하고 직관적인 선형 청산 프로세스
 */
class CXExitManager : public IXExitManager {
private:
    ulong               m_magic;
    string              m_sid;
    CTrade              m_trade;

public:
    CXExitManager(string sid = "") : m_sid(sid), m_magic(0) {}
    ~CXExitManager() {}

    virtual void SetMagic(ulong magic) override { m_magic = magic; m_trade.SetExpertMagicNumber(magic); }
    virtual void SetSid(string sid) override   { m_sid = sid; }
    virtual void Reset() override { m_magic = 0; m_sid = ""; }

    virtual void Execute(CXParam* xp) override {
        if(IS_INVALID(xp) || IS_NULL(xp.sig_ptr)) return;

        if(m_sid == "") m_sid = xp.sig_ptr.sid;
        CXSignal* sig = xp.sig_ptr;

        // Step 1. 터미널 자산 검색 및 존재 여부 판단
        int pos_count = 0;
        int ord_count = 0;

        if(sig.ticket > 0) {
            if(PositionSelectByTicket((ulong)sig.ticket)) pos_count++;
            if(OrderSelect((ulong)sig.ticket)) ord_count++;
        }

        if (pos_count == 0 && ord_count == 0) {
            // Count by comment just in case
            for(int i = PositionsTotal() - 1; i >= 0; i--) {
                ulong t = PositionGetTicket(i);
                if(PositionSelectByTicket(t) && PositionGetString(POSITION_COMMENT) == m_sid) pos_count++;
            }
            for(int i = OrdersTotal() - 1; i >= 0; i--) {
                ulong t = OrderGetTicket(i);
                if(OrderSelect(t) && OrderGetString(ORDER_COMMENT) == m_sid) ord_count++;
            }
        }

        XP_LOG_INFO(xp, StringFormat("[EXIT-CHECK] SID: %s, Found Pos: %d, Ord: %d", m_sid, pos_count, ord_count));

        if(pos_count == 0 && ord_count == 0) {
            // 이미 청산됨
            sig.SetStatus(XE_CLOSED_SIGNAL, "Asset already closed or not found");
            CXDatabase* db = CX_GET_OBJ(xp.ctx, CXDatabase, "db");
            if(IS_VALID(db)) {
                CXSignalRepository repo(db);
                repo.UpdateStatus(sig);
            }
            return;
        }

        // Step 2 & 3. 청산 시도
        CloseAllSync(xp);

        // 동기적으로 상태를 20으로 덮어쓰지 않음. (트랜잭션에 위임)
    }

    virtual int CloseAllSync(CXParam* xp) override {
        if(XP_INVALID(xp) || IS_NULL(xp.sig_ptr)) return 0;
        CXSignal* req = xp.sig_ptr;
        ulong db_ticket = (ulong)req.ticket;
        string target_gid = CXUtil::GetGidFromSid(m_sid);

        // [v7.14] Context로부터 전략 객체 획득 (Interface Injection)
        int exit_mode = 1; // 1: 개별, 2: 그룹
        IXTradingStrategy* strategy = NULL;
        if(XP_VALID(xp) && IS_VALID(xp.ctx)) strategy = CX_GET_OBJ(xp.ctx, IXTradingStrategy, "strategy");
        if(IS_VALID(strategy)) exit_mode = strategy.EvaluateExit(xp);

        int processed = 0;

        CXParam temp;
        temp.sid = target_gid;
        temp.ctx = xp.ctx;
        temp.sig_ptr = req;

        // 개별 청산 모드
        if(exit_mode == 1) {
            if(db_ticket > 0) {
                temp.ticket = (long)db_ticket;
                if(CloseByTicket(GetPointer(temp))) processed++;
                if(DeleteByTicket(GetPointer(temp))) processed++;
            }

            // Step 3. Fallback
            if(IsPositionExists(m_sid) || IsOrderExists(m_sid)) {
                XP_LOG_WARN(xp, StringFormat("[EXIT-FALLBACK] Ticket retry failed. Force closing by SID comment: %s", m_sid));
                processed += CloseAllBySID(GetPointer(temp));
            }
        } 
        // 그룹 청산 모드
        else if(exit_mode == 2) {
            processed += CloseAllByGID(GetPointer(temp));
            processed += CancelAllByGID(GetPointer(temp));
        }

        return processed;
    }

private:
    bool CloseByTicket(CXParam* xp) {
        if(IS_INVALID(xp) || IS_NULL(xp.sig_ptr)) return false;
        ulong ticket = (ulong)xp.ticket;
        string sid = xp.sig_ptr.sid;

        if(ticket > 0 && PositionSelectByTicket(ticket)) {
            m_trade.SetExpertMagicNumber((long)PositionGetInteger(POSITION_MAGIC));
            bool res = m_trade.PositionClose(ticket);
            XP_LOG_INFO(xp, StringFormat("[EXIT-TICKET] Executing Close for Ticket: %lld, SID: %s. Result: %s", ticket, sid, res ? "true" : "false"));
            if(res && VerifyPhysicalAbsence(xp, ticket, true)) return true;
        }
        return false;
    }

    bool DeleteByTicket(CXParam* xp) {
        if(IS_INVALID(xp) || IS_NULL(xp.sig_ptr)) return false;
        ulong ticket = (ulong)xp.ticket;
        string sid = xp.sig_ptr.sid;

        if(ticket > 0 && OrderSelect(ticket)) {
            bool res = m_trade.OrderDelete(ticket);
            XP_LOG_INFO(xp, StringFormat("[EXIT-TICKET] Executing Delete for Ticket: %lld, SID: %s. Result: %s", ticket, sid, res ? "true" : "false"));
            if(res && VerifyPhysicalAbsence(xp, ticket, false)) return true;
        }
        return false;
    }

    int CloseAllBySID(CXParam* xp) {
        int count = 0;
        string sid = xp.sig_ptr.sid;
        for(int i = PositionsTotal() - 1; i >= 0; i--) {
            ulong t = PositionGetTicket(i);
            if(PositionSelectByTicket(t) && PositionGetString(POSITION_COMMENT) == sid) {
                m_trade.SetExpertMagicNumber((long)PositionGetInteger(POSITION_MAGIC));
                bool res = m_trade.PositionClose(t);
                XP_LOG_INFO(xp, StringFormat("[EXIT-TICKET] Executing Close for Ticket: %lld, SID: %s. Result: %s", t, sid, res ? "true" : "false"));
                if(res) count++;
            }
        }
        for(int i = OrdersTotal() - 1; i >= 0; i--) {
            ulong t = OrderGetTicket(i);
            if(OrderSelect(t) && OrderGetString(ORDER_COMMENT) == sid) {
                bool res = m_trade.OrderDelete(t);
                XP_LOG_INFO(xp, StringFormat("[EXIT-TICKET] Executing Delete for Ticket: %lld, SID: %s. Result: %s", t, sid, res ? "true" : "false"));
                if(res) count++;
            }
        }
        return count;
    }

    bool VerifyPhysicalAbsence(CXParam* xp, ulong ticket, bool is_position) {
        // [v7.5] Non-blocking check. Async confirmation will be handled via OnTradeTransaction.
        if(is_position) return !PositionSelectByTicket(ticket);
        return !OrderSelect(ticket);
    }

    bool IsPositionExists(string sid) {
        for(int i = PositionsTotal() - 1; i >= 0; i--) {
            ulong t = PositionGetTicket(i);
            if(PositionSelectByTicket(t) && PositionGetString(POSITION_COMMENT) == sid) return true;
        }
        return false;
    }

    bool IsOrderExists(string sid) {
        for(int i = OrdersTotal() - 1; i >= 0; i--) {
            ulong t = OrderGetTicket(i);
            if(OrderSelect(t) && OrderGetString(ORDER_COMMENT) == sid) return true;
        }
        return false;
    }

    // GID logics...
    void FindAssetsByGID(CXParam* xp) {
        if(IS_INVALID(xp) || IS_NULL(xp.data)) return;
        CArrayObj* containers = (CArrayObj*)xp.data;
        if(containers.Total() < 2) return;

        CArrayLong* out_positions = (CArrayLong*)containers.At(0);
        CArrayLong* out_orders = (CArrayLong*)containers.At(1);
        string gid = xp.sid; 

        out_positions.Clear(); out_orders.Clear();
        for(int i = PositionsTotal() - 1; i >= 0; i--) {
            ulong t = PositionGetTicket(i);
            if(PositionSelectByTicket(t) && StringFind(PositionGetString(POSITION_COMMENT), gid) >= 0) out_positions.Add((long)t);
        }
        for(int i = OrdersTotal() - 1; i >= 0; i--) {
            ulong t = OrderGetTicket(i);
            if(OrderSelect(t) && StringFind(OrderGetString(ORDER_COMMENT), gid) >= 0) out_orders.Add((long)t);
        }
    }

    int CloseAllByGID(CXParam* xp) {
        if(IS_INVALID(xp)) return 0;
        CArrayObj containers;
        CArrayLong pos_tickets, ord_tickets;
        containers.Add(GetPointer(pos_tickets));
        containers.Add(GetPointer(ord_tickets));

        xp.data = GetPointer(containers);
        FindAssetsByGID(xp);
        xp.data = NULL;

        int count = 0;
        for(int i = 0; i < pos_tickets.Total(); i++) {
            xp.ticket = pos_tickets.At(i);
            if(CloseByTicket(xp)) count++;
        }
        return count;
    }

    int CancelAllByGID(CXParam* xp) {
        if(IS_INVALID(xp)) return 0;
        CArrayObj containers;
        CArrayLong pos_tickets, ord_tickets;
        containers.Add(GetPointer(pos_tickets));
        containers.Add(GetPointer(ord_tickets));

        xp.data = GetPointer(containers);
        FindAssetsByGID(xp);
        xp.data = NULL;

        int count = 0;
        for(int i = 0; i < ord_tickets.Total(); i++) {
            xp.ticket = ord_tickets.At(i);
            if(DeleteByTicket(xp)) count++;
        }
        return count;
    }
};
#endif

