/**
 * @class CXSignalWatcher
 * @brief 신규 신호 감시 시퀀스 통합 관리 담당
 */
class CXSignalWatcher {
private:
    IRepository*        m_repo;
    ICXConfig*          m_config;
    ICXContext*         m_ctx;
    ICXFluentSequence*  m_sequence;

public:
    CXSignalWatcher(IRepository* repo, ICXConfig* config) 
        : m_repo(repo), m_config(config) {

        m_ctx = new CXContext();
        if(IS_VALID(m_ctx)) {
            m_ctx.Set("repo", m_repo);
            m_ctx.Set("config", m_config);
        }

        m_sequence = new CXFluentSequence(m_ctx, "WatcherSeq");
        InitSequence();
    }

    ~CXSignalWatcher() {
        SAFE_DELETE(m_sequence);
        SAFE_DELETE(m_ctx);
    }

    /**
     * @brief 주기적 신호 감시 시퀀스 구동
     */
    void Pulse(ICXParam* xp) {
        if(IS_VALID(m_sequence)) {
            m_sequence.Pulse(xp);
        }
    }

private:
    void InitSequence() {
        CXFluentSequence* seq = dynamic_cast<CXFluentSequence*>(m_sequence);
        if(IS_INVALID(seq)) return;

        //-- Watcher 시퀀스 정의: Discovery -> Validation -> Binding
        seq.From(0).Execute(new CXStepDiscovery()).OnSuccess(1);
        seq.From(1).Execute(new CXStepValidation()).OnSuccess(2).OnFail(0);
        seq.From(2).Execute(new CXStepBinding()).OnSuccess(0);

        seq.Build();
    }
};

