 */
class CXTrailingFixed : public IXTrailingStrategy {
private:
    IXPriceTracker* m_tracker;
    double          m_targetPrice;
    string          m_name;

public:
    CXTrailingFixed(string name) : m_name(name), m_targetPrice(0) {
        m_tracker = new CXPriceTracker();
    }

    virtual ~CXTrailingFixed() {
        SAFE_DELETE(m_tracker);
    }

    virtual string Name() const override { return m_name; }
    virtual double TargetPrice() const override { return m_targetPrice; }

    /**
     * @brief 트레일링 계산 (진트/익트 공용)
     */
    virtual double Calculate(ICXParam* xp, ICXContext* ctx) override {
        CXSignal* sig = dynamic_cast<CXSignal*>(xp.GetSignal());
        if(IS_INVALID(sig) || IS_INVALID(m_tracker)) return 0;

        // 1. 컨텍스트에서 통합 로거(Dispatcher) 획득
        ICXLogger* logger = (ICXLogger*)ctx.Get("logger");

        double currentPrice = SymbolInfoDouble(sig.symbol, (sig.dir == CX_DIR_BUY) ? SYMBOL_BID : SYMBOL_ASK);
        m_tracker.Update(currentPrice);

        // 2. 고점/저점 갱신 시 상세 로그 (File 채널 위주 기록 기대)
        if(IS_VALID(logger)) {
            logger.Log(LOG_LVL_TRACE, StringFormat("[%s] Cur:%.5f, High:%.5f, Low:%.5f", 
                       m_name, currentPrice, m_tracker.GetHighest(), m_tracker.GetLowest()));
        }

        //-- [로직 예시] 실제 복합 계산 수식 포팅 지점
        // ... 실제 트레일링 가격 계산 로직 수행 ...

        if(m_targetPrice > 0 && IS_VALID(logger)) {
            logger.Log(LOG_LVL_INFO, StringFormat("[%s] New Target Price: %.5f", m_name, m_targetPrice));
        }

        return m_targetPrice; 
    }

    virtual void Reset() override {
        m_targetPrice = 0;
        if(IS_VALID(m_tracker)) m_tracker.Reset();
    }
};

