/**
 * @brief 진입 주문 실행 (xa_entry 기반)
 */
void ExecuteEntry(ICXParam* xp) {
    if(m_ctx == NULL || xp == NULL) return;

    CXSignal* sig = dynamic_cast<CXSignal*>(xp.GetSignal());
    if(IS_INVALID(sig)) return;

    m_sid = sig.sid;
    XP_LOG_INFO(xp, StringFormat("[EXEC-ENTRY] SID:%s, Dir:%d, Type:%d, Lot:%.2f, Price:%.5f", 
               m_sid, sig.dir, sig.type, sig.lot, sig.price_signal));

    bool res = false;

    //--- 주문 실행 (시장가 vs 지정가)
    if(sig.type == ORDER_MARKET) {
        res = (sig.dir == CX_DIR_BUY) ? m_trade.Buy(sig.lot, sig.symbol, 0, sig.sl, sig.tp, m_sid)
                                      : m_trade.Sell(sig.lot, sig.symbol, 0, sig.sl, sig.tp, m_sid);
    }
    else {
        res = (sig.dir == CX_DIR_BUY) ? m_trade.BuyLimit(sig.lot, sig.price_signal, sig.symbol, sig.sl, sig.tp, ORDER_TIME_GTC, 0, m_sid)
                                      : m_trade.SellLimit(sig.lot, sig.price_signal, sig.symbol, sig.sl, sig.tp, ORDER_TIME_GTC, 0, m_sid);
    }

    if(!res) {
        XP_LOG_ERROR(xp, StringFormat("[EXEC-FAIL] RetCode:%d, Msg:%s", m_trade.ResultRetcode(), m_trade.ResultRetcodeDescription()));
        sig.xe_status = XE_ERROR;
        sig.xe_status_msg = "Execution Failed: " + m_trade.ResultRetcodeDescription();
    }
    else {
        m_ticket = m_trade.ResultOrder();
        sig.ticket = (long)m_ticket;

        if(sig.type == ORDER_MARKET) {
            sig.xe_status = XE_EXECUTED;
            sig.xe_status_msg = "[EXEC] Market Entry Success";
        } else {
            sig.xe_status = XE_PENDING_PLACED;
            sig.xe_status_msg = StringFormat("[PENDING] Limit Order Placed (Tkt:%lld)", m_ticket);
        }
        XP_LOG_OK(xp, sig.xe_status_msg);
    }

    // DB 상태 업데이트는 리포지토리에 위임 (Step에서 수행 권장)
}

