//+------------------------------------------------------------------+
//|                                         CXStateReconciler.mqh    |
//|                                  Copyright 2026, Gemini CLI      |
//| [v7.3] Resolves state differences between Terminal and DB        |
//+------------------------------------------------------------------+
#ifndef CX_STATE_RECONCILER_MQH
#define CX_STATE_RECONCILER_MQH

#include "CXTerminalEvent.mqh"
#include "..\..\Infra\Database\CXSignalRepository.mqh"
#include "..\..\Infra\Database\CXDatabase.mqh"
#include "..\..\Infra\Logging\IXLogService.mqh"
#include "..\..\Domain\Execution\CXPositionManager.mqh"
#include <Trade\Trade.mqh>

/**
 * @class CXStateReconciler
 * @brief Observer가 수집한 터미널 이벤트를 DB 상태와 비교하여 불일치(Drift)를 해결
 */
class CXStateReconciler : public CObject {
private:
    CXDatabase*       m_db;
    IXLogService*     m_log;

public:
    CXStateReconciler(CXDatabase* db, IXLogService* log) : m_db(db), m_log(log) {}

    /**
     * @brief 큐에 쌓인 이벤트를 하나씩 소비하며 상태 동기화 수행
     */
    void Reconcile(CXParam* xp) {
        CArrayObj* queue = CX_CAST(CArrayObj, xp.data);
        if(queue == NULL || queue.Total() == 0) return;

        CXSignalRepository repo(m_db);
        CArrayObj db_signals;
        repo.GetActiveSignals(GetPointer(db_signals));

        // ProcessEvent에서 공유할 DB 신호 리스트를 caller에 임시 저장
        CObject* prev_caller = xp.caller;
        xp.caller = GetPointer(db_signals); 

        while(queue.Total() > 0) {
            CXTerminalEvent* ev = (CXTerminalEvent*)queue.Detach(0);
            if(ev == NULL) continue;

            // 이벤트 데이터를 xp 캐리어에 실어서 전달
            xp.ticket = (long)ev.ticket;
            xp.i_val1 = ev.type; // 이벤트 타입
            xp.sid    = ev.comment;
            xp.magic  = ev.magic;

            ProcessEvent(xp, repo);
            delete ev;
        }
        xp.caller = prev_caller; // 원상 복구

        // [Phase 1.5] External Close 감지 (DB에는 있지만 터미널엔 없는 경우)
        for(int j = 0; j < db_signals.Total(); j++) {
            CXSignal* sig = CX_CAST(CXSignal, db_signals.At(j));
            CheckExternalClose(sig, repo);
        }
    }

private:
    void ProcessEvent(CXParam* xp, CXSignalRepository &repo) {
        CArrayObj* db_signals = CX_CAST(CArrayObj, xp.caller);
        CArrayObj* reverse_inject_queue = xp.filter_list; 

        // 1. 포지션 이벤트 처리
        if(xp.i_val1 == TE_EVENT_POSITION_CHANGE || xp.i_val1 == TE_EVENT_PERIODIC_SCAN) {
            if(PositionSelectByTicket((ulong)xp.ticket)) {
                if(!IsManaged(xp.magic, xp.filter_magics)) return;

                if(xp.sid == "") return;

                CXSignal* sig = repo.FindByComment(xp.sid, db_signals);
                if(IS_VALID(sig)) {
                    if(sig.xe_status >= XE_CLOSED_SIGNAL) {
                        if(IS_VALID(m_log)) {
                            CXParam xl; xl.sid = sig.sid; xl.log_svc = m_log;
                            XP_LOG_WARN(GetPointer(xl), StringFormat("[RECONCILE] Orphan Position Found. Closing SID: %s", sig.sid));
                        }
                        ClosePosition((ulong)xp.ticket, xp.magic);
                    }
                } else {
                    int db_status = repo.GetStatusBySid(xp.sid);
                    if(db_status == -1) {
                        if(IS_VALID(m_log)) {
                            CXParam xl; xl.sid = xp.sid; xl.log_svc = m_log;
                            XP_LOG_ERROR(GetPointer(xl), StringFormat("[FATAL-ASYNC] Position exists but NO DB RECORD found for SID: %s. Forcing Liquidation for safety.", xp.sid));
                        }
                        ClosePosition((ulong)xp.ticket, xp.magic);
                    }
                    else if(db_status >= XE_CLOSED_SIGNAL) {
                        if(IS_VALID(m_log)) {
                            CXParam xl; xl.sid = xp.sid; xl.log_svc = m_log;
                            XP_LOG_WARN(GetPointer(xl), StringFormat("[RECONCILE] Position for closed SID: %s. Forcing Close.", xp.sid));
                        }
                        ClosePosition((ulong)xp.ticket, xp.magic);
                    }
                    else {
                        if(IS_VALID(reverse_inject_queue)) {
                            CXTerminalEvent* rev_ev = new CXTerminalEvent((ENUM_TERMINAL_EVENT_TYPE)xp.i_val1, (ulong)xp.ticket, xp.sid, xp.magic);
                            reverse_inject_queue.Add(rev_ev);
                        }
                    }
                }
            }
        }

        // 2. 대기 오더 이벤트 처리
        if(xp.i_val1 == TE_EVENT_ORDER_CHANGE || xp.i_val1 == TE_EVENT_PERIODIC_SCAN) {
            if(OrderSelect((ulong)xp.ticket)) {
                if(!IsManaged(xp.magic, xp.filter_magics)) return;

                if(xp.sid == "") return;

                CXSignal* sig = repo.FindByComment(xp.sid, db_signals);
                if(sig == NULL) {
                    int db_status = repo.GetStatusBySid(xp.sid);
                    // DB에 없거나 아직 로드되지 않은 경우 역주입 대상
                    if(db_status == -1 || db_status < XE_PENDING_PLACED) {
                        if(reverse_inject_queue != NULL) {
                            CXTerminalEvent* rev_ev = new CXTerminalEvent((ENUM_TERMINAL_EVENT_TYPE)xp.i_val1, (ulong)xp.ticket, xp.sid, xp.magic);
                            reverse_inject_queue.Add(rev_ev);
                        }
                    }
                }
            }
        }
    }

    bool IsManaged(long mgc, CArrayInt* managed_magics) {
        if(managed_magics == NULL) return false;
        for(int i=0; i<managed_magics.Total(); i++) if(managed_magics.At(i) == mgc) return true;
        return false;
    }

    void ClosePosition(ulong ticket, long magic) {
        CTrade trade; trade.SetExpertMagicNumber(magic);
        trade.PositionClose(ticket);
    }

    void CheckExternalClose(CXSignal* sig, CXSignalRepository &repo) {
        if(sig.xe_status == XE_EXECUTED || sig.xe_status == XE_EXECUTING_MARKET) {
            if(!PositionSelectByTicket((ulong)sig.ticket)) {
                if(sig.xe_status == XE_EXECUTING_MARKET) return; 

                sig.SetStatus(XE_CLOSED_SIGNAL, "[CLOSED-EXT] Disappeared");
                if(HistorySelectByPosition((ulong)sig.ticket)) {
                    int deals = HistoryDealsTotal();
                    for(int k=deals-1; k>=0; k--) {
                        ulong deal_ticket = HistoryDealGetTicket(k);
                        if(HistoryDealGetInteger(deal_ticket, DEAL_ENTRY) == DEAL_ENTRY_OUT) {
                            sig.price_close = HistoryDealGetDouble(deal_ticket, DEAL_PRICE);
                            string reason = HistoryDealGetString(deal_ticket, DEAL_COMMENT);
                            if(StringFind(reason, "tp") >= 0) sig.SetStatus(XE_CLOSED_TP, "[CLOSED-EXT] Take Profit Hit");
                            else if(StringFind(reason, "sl") >= 0) sig.SetStatus(XE_CLOSED_SL, "[CLOSED-EXT] Stop Loss Hit");
                            break;
                        }
                    }
                }
                repo.UpdateStatus(sig);
            }
        }
    }
    };
    #endif

