#include "CXFluentSequence.mqh"

class CXTradingSession {
private:
    IRepository*       m_repo;
    ICXContext*        m_context;
    CXEntryManager*    m_entryMgr;
    CXOrderManager*    m_orderMgr;
    CXPositionManager* m_posMgr;
    CXExitManager*     m_exitMgr;
    CXFluentSequence*  m_sequence;

public:
    CXTradingSession(IRepository* repo, ICXContext* context) 
        : m_repo(repo), m_context(context) {
        m_entryMgr = new CXEntryManager();
        m_orderMgr = new CXOrderManager();
        m_posMgr = new CXPositionManager();
        m_exitMgr = new CXExitManager();
        m_sequence = new CXFluentSequence();
    }
    ~CXTradingSession() {
        delete m_entryMgr;
        delete m_orderMgr;
        delete m_posMgr;
        delete m_exitMgr;
        delete m_sequence;
    }
};

#endif

