#ifndef CXPAYLOADER_MQH
#define CXPAYLOADER_MQH

#include "..\Interfaces\ICXParam.mqh"
#include "..\Interfaces\ICXSignal.mqh"
#include "..\Interfaces\ICXContext.mqh"

/**
 * @class CXPayloader
 * @brief CXParam을 확장하여 시스템 전반에서 데이터를 실어 나르는 범용 캐리어 클래스
 * @details 별도의 매개변수 구조체를 생성하지 않고, CXParam(ICXParam)을 페이로더로 활용하여
 *          레이어 간 유연한 데이터 전달 및 타입 안전성을 보장함.
 */
class CXPayloader : public ICXParam {
private:
    ICXSignal*  m_signal;     // 현재 처리 중인 신호 객체
    ICXContext* m_context;    // 시스템 컨텍스트 (DI 컨테이너 역할)

    //-- 범용 데이터 캐리어 (Payload)
    long        m_lVal;       // 티켓 번호, 매직 넘버 등
    double      m_dVal;       // 가격, 수량 등
    string      m_sVal;       // SID, 상태 메시지 등
    int         m_iVal;       // 이벤트 타입, 상태 코드 등
    CObject*    m_data;       // 확장 객체 (CArrayObj 등)

public:
    CXPayloader() : m_signal(NULL), m_context(NULL), m_lVal(0), m_dVal(0), m_sVal(""), m_iVal(0), m_data(NULL) {}
    ~CXPayloader() {}

    //-- 기본 인터페이스 구현
    virtual ICXSignal* GetSignal() override { return m_signal; }

    //-- Fluent Interface 방식의 Setter (Chaining 지원)
    CXPayloader* SetSignal(ICXSignal* sig)  { m_signal = sig;  return GetPointer(this); }
    CXPayloader* SetContext(ICXContext* ctx) { m_context = ctx; return GetPointer(this); }
    CXPayloader* SetLong(long val)          { m_lVal = val;    return GetPointer(this); }
    CXPayloader* SetDouble(double val)      { m_dVal = val;    return GetPointer(this); }
    CXPayloader* SetString(string val)      { m_sVal = val;    return GetPointer(this); }
    CXPayloader* SetInt(int val)            { m_iVal = val;    return GetPointer(this); }
    CXPayloader* SetData(CObject* data)     { m_data = data;   return GetPointer(this); }

    //-- Getter
    ICXContext*  GetContext() { return m_context; }
    long         GetLong()    { return m_lVal; }
    double       GetDouble()  { return m_dVal; }
    string       GetString()  { return m_sVal; }
    int          GetInt()     { return m_iVal; }
    CObject*     GetData()    { return m_data; }

    /**
     * @brief 페이로더 초기화 (재사용 시 활용)
     */
    void Reset() {
        m_signal = NULL;
        m_context = NULL;
        m_lVal = 0;
        m_dVal = 0;
        m_sVal = "";
        m_iVal = 0;
        m_data = NULL;
    }
};

#endif

