    CTrade          m_trade;
    ICXContext*     m_ctx;

public:
    CXOrderManager(ICXContext* ctx) : m_ctx(ctx), m_ticket(0), m_sid("") {}
    ~CXOrderManager() {}

    void SetMagic(ulong magic) { m_trade.SetExpertMagicNumber(magic); }

    /**
     * @brief 진입 주문 실행 (xa_entry 기반)
     */
    void ExecuteEntry(ICXParam* xp) {
        if(m_ctx == NULL || xp == NULL) return;

        // 1. 신호 획득
        ICXSignal* signal = xp.GetSignal();
        if(signal == NULL) return;

        // 2. 주문 실행 로직 (기존 CXOrderManager 로직 포팅 및 고도화)
        // ...

        XP_LOG_INFO(xp, StringFormat("[SANDBOX-EXEC] Order Execution for SID: %s", m_sid));
    }

    /**
     * @brief 터미널 오더 상태 동기화
     */
    bool SelectOrder(ICXParam* xp) {
        // 오더 선택 로직
        return false;
    }

    void Reset() {
        m_ticket = 0;
        m_sid = "";
    }
};

#endif

