        SAFE_DELETE(m_entryMgr);
        SAFE_DELETE(m_orderMgr);
        SAFE_DELETE(m_posMgr);
        SAFE_DELETE(m_exitMgr);
        SAFE_DELETE(m_sequence);
        SAFE_DELETE(m_logger);
        SAFE_DELETE(m_ctx);
    }

