    /**
     * @brief 활성 의도가 있는 신호 목록 조회 및 객체 매핑
     */
    int LoadActiveSignals(CArrayObj* list) {
        if(m_db == NULL || list == NULL) return 0;

        string sql = "SELECT id, sid, gid, symbol, dir, type, lot, price_signal, tp, sl, te_start, te_step, ts_start, ts_step, xa_entry, xa_exit, xe_status FROM signals WHERE (xa_entry > 0 OR xa_exit > 0) AND xa_status != 6";
        int handle = m_db.GetHandle();
        int req = DatabasePrepare(handle, sql);
        if(req == INVALID_HANDLE) return 0;

        int count = 0;
        while(DatabaseRead(req)) {
            CXSignal* sig = new CXSignal();
            DatabaseColumnInteger(req, 0, sig.id);
            DatabaseColumnString(req, 1, sig.sid);
