#include "..\..\..\Models\CXParam.mqh"
#include "..\..\..\Session\CXTradingSession.mqh"

/**
 * @class CXStepBinding
 * @brief 검증된 신호를 SessionPool에서 세션에 할당하고 기동하는 단계
 */
class CXStepBinding : public IXStep {
public:
    CXStepBinding() {}
    virtual ~CXStepBinding() {}

    virtual string Name() override { return "Step_Binding"; }

    virtual bool OnCondition(ICXParam* xp, ICXContext* ctx, int current_state) override {
        return (ctx.Get("active_signals") != NULL);
    }

    virtual int OnProcess(ICXParam* xp, ICXContext* ctx) override {
        CArrayObj* activeList = (CArrayObj*)ctx.Get("active_signals");
        if(IS_INVALID(activeList)) return 0;

        ICXLogger* logger = (ICXLogger*)ctx.Get("logger");

        for(int i = 0; i < activeList.Total(); i++) {
            CXSignal* sig = (CXSignal*)activeList.At(i);

            //-- 1. AppService의 StartSession 연동 (여기서는 예시적으로 ctx에서 조회)
            // 실제로는 AppService가 이 Step의 결과를 받아 처리하거나, Step이 Pool에 접근
            // (구조상 AppService가 Orchestrator이므로 여기서 신호를 세션에 주입)

            if(IS_VALID(logger)) logger.Log(LOG_LVL_INFO, StringFormat("[BINDING] Mapping SID:%s to Sandbox Session", sig.sid));
        }

        //-- 작업 완료 후 목록 초기화
        activeList.Clear();
        ctx.Set("active_signals", NULL);
        SAFE_DELETE(activeList);

        return 0; // 다시 탐색(Discovery) 상태로 복귀
    }

    virtual void OnEnter(ICXContext* ctx) override {}
    virtual void OnExit(ICXContext* ctx) override {}
};

