CXAppService::CXAppService(ICXConfig* config, int poolSize = 50) : m_config(config) {
    m_db = new CXDatabase();
    if(IS_INVALID(m_db)) return;

    if(m_db.Open()) {
        m_repo = new CXSignalRepository(m_db);
    }
    if(IS_INVALID(m_repo)) return;

    m_watcher = new CXSignalWatcher(m_repo, m_config);
    if(IS_INVALID(m_watcher)) return;

    m_sessionPool = new CXTradingSessionPool(poolSize);
    if(IS_INVALID(m_sessionPool)) return;

    m_globalContext = new CXContext();
    if(IS_INVALID(m_globalContext)) return;

    m_sessionPool.Initialize(m_repo, m_globalContext);
}

CXAppService::~CXAppService() {
    SAFE_DELETE(m_db);
    SAFE_DELETE(m_repo);
    SAFE_DELETE(m_watcher);
    SAFE_DELETE(m_sessionPool);
    SAFE_DELETE(m_globalContext);
}

CXTradingSession* CXAppService::StartSession(ICXParam* param) {
    return m_sessionPool.BorrowSession();
}

#endif

