/**
 * @brief 활성 세션들에 대해 주기적 로직(Pulse) 실행
 */
void Pulse(ICXParam* xp) {
    for(int i = 0; i < m_active.Total(); i++) {
        CXTradingSession* session = (CXTradingSession*)m_active.At(i);
        if(IS_VALID(session)) session.Pulse(xp);
    }
    PurgeClosed();
}

/**
 * @brief 종료된 세션을 감지하여 풀로 반환
 */
void PurgeClosed() {
    for(int i = m_active.Total() - 1; i >= 0; i--) {
        CXTradingSession* session = (CXTradingSession*)m_active.At(i);
        if(IS_VALID(session) && !session.IsActive()) {
            ReturnSession(session);
        }
    }
}

/**
 * @brief 매 틱 주기적 업데이트 (Watcher 및 활성 세션 Pulse)
 */
void Pulse() {
    CXParam xp; // 기본 틱 페이로더

    // 1. 신호 감시 시퀀스 구동
    if(IS_VALID(m_watcher)) m_watcher.Pulse(GetPointer(xp));

    // 2. 활성 세션 시퀀스 구동 (Pool 내부 순회)
    if(IS_VALID(m_sessionPool)) m_sessionPool.Pulse(GetPointer(xp));
}

