#ifndef CXTRAILINGFIXED_MQH
#define CXTRAILINGFIXED_MQH

#include "..\..\Interfaces\IXTrailingStrategy.mqh"
#include "..\..\Interfaces\IXPriceTracker.mqh"
#include "..\..\Models\CXSignal.mqh"
#include "CXPriceTracker.mqh"

#include "..\..\Interfaces\ICXLogger.mqh"

/**
 * @class CXTrailingFixed
 * @brief 고정 포인트(Step) 기반의 표준 트레일링 전략
 */
class CXTrailingFixed : public IXTrailingStrategy {
private:
    IXPriceTracker* m_tracker;
    double          m_targetPrice;
    string          m_name;

public:
    CXTrailingFixed(string name) : m_name(name), m_targetPrice(0) {
        m_tracker = new CXPriceTracker();
    }

    virtual ~CXTrailingFixed() {
        SAFE_DELETE(m_tracker);
    }

    virtual string Name() const override { return m_name; }
    virtual double TargetPrice() const override { return m_targetPrice; }

    /**
     * @brief 트레일링 계산 (진트/익트 공용)
     */
    virtual double Calculate(ICXParam* xp, ICXContext* ctx) override {
        CXSignal* sig = dynamic_cast<CXSignal*>(xp.GetSignal());
        if(IS_INVALID(sig) || IS_INVALID(m_tracker)) return 0;

        ICXLogger* logger = (ICXLogger*)ctx.Get("logger");
        double point = SymbolInfoDouble(sig.symbol, SYMBOL_POINT);
        double currentPrice = SymbolInfoDouble(sig.symbol, (sig.dir == CX_DIR_BUY) ? SYMBOL_BID : SYMBOL_ASK);
        m_tracker.Update(currentPrice);

        double target = 0;

        //--- Case A: 진입 트레일링 (Entry Trailing)
        if(sig.xe_status == XE_PENDING_PLACED && sig.te_start > 0) {
            if(sig.dir == CX_DIR_BUY) {
                // Buy: 가격이 내려가면 진입가도 따라 내려감 (더 낮은 가격 추적)
                target = currentPrice - sig.te_start * point;
                if(target < sig.price_signal - sig.te_step * point) {
                    m_targetPrice = NormalizeDouble(target, (int)SymbolInfoInteger(sig.symbol, SYMBOL_DIGITS));
                }
            }
            else if(sig.dir == CX_DIR_SELL) {
                // Sell: 가격이 올라가면 진입가도 따라 올라감 (더 높은 가격 추적)
                target = currentPrice + sig.te_start * point;
                if(target > sig.price_signal + sig.te_step * point) {
                    m_targetPrice = NormalizeDouble(target, (int)SymbolInfoInteger(sig.symbol, SYMBOL_DIGITS));
                }
            }
        }
        //--- Case B: 익절 트레일링 (Exit Trailing / TS)
        else if(sig.xe_status >= XE_EXECUTED && sig.ts_start > 0) {
            double highest = m_tracker.GetHighest();
            double lowest  = m_tracker.GetLowest();

            if(sig.dir == CX_DIR_BUY) {
                double profit = currentPrice - sig.price_open;
                if(profit >= sig.ts_start * point) {
                    target = highest - sig.ts_start * point; // 고점 대비 일정 거리 유지
                    if(target > sig.sl + sig.ts_step * point) {
                        m_targetPrice = NormalizeDouble(target, (int)SymbolInfoInteger(sig.symbol, SYMBOL_DIGITS));
                    }
                }
            }
            else if(sig.dir == CX_DIR_SELL) {
                double profit = sig.price_open - currentPrice;
                if(profit >= sig.ts_start * point) {
                    target = lowest + sig.ts_start * point;
                    if(target < sig.sl - sig.ts_step * point || sig.sl == 0) {
                        m_targetPrice = NormalizeDouble(target, (int)SymbolInfoInteger(sig.symbol, SYMBOL_DIGITS));
                    }
                }
            }
        }

        if(m_targetPrice > 0 && IS_VALID(logger)) {
            logger.Log(LOG_LVL_TRACE, StringFormat("[%s] Recalculated Target: %.5f (Current: %.5f)", m_name, m_targetPrice, currentPrice));
        }

        return m_targetPrice; 
    }

    virtual void Reset() override {
        m_targetPrice = 0;
        if(IS_VALID(m_tracker)) m_tracker.Reset();
    }
};

#endif

#ifndef CXEXITMANAGER_MQH
#define CXEXITMANAGER_MQH

#include "..\..\Interfaces\ICXContext.mqh"
#include "..\..\Interfaces\ICXParam.mqh"
#include "..\..\Interfaces\CXDefine.mqh"
#include "..\..\Interfaces\CXMacros.mqh"
#include <Trade\Trade.mqh>

/**
 * @class CXExitManager
 * @brief 샌드박스 세션 내의 청산 및 주문 취소 담당 (3-Layer Guard)
 */
class CXExitManager {
private:
    ulong           m_magic;
    ICXContext*     m_ctx;
    CTrade          m_trade;

public:
    CXExitManager(ICXContext* ctx) : m_ctx(ctx), m_magic(0) {}
    ~CXExitManager() {}

    void SetMagic(ulong magic) { m_magic = magic; m_trade.SetExpertMagicNumber(magic); }

    /**
     * @brief 3-Layer Guard 청산 실행
     * @return true: 모든 자산 소멸 확인됨, false: 잔여 자산 존재 (재시도 필요)
     */
    bool Execute(ICXParam* xp) {
        if(m_ctx == NULL || xp == NULL) return false;
        CXSignal* sig = dynamic_cast<CXSignal*>(xp.GetSignal());
        if(IS_INVALID(sig)) return false;

        string sid = sig.sid;
        XP_LOG_INFO(xp, StringFormat("[EXIT-START] Liquidation for SID: %s", sid));

        //-- Layer 1 & 2: 청산 실행
        CloseByTicket(sig);
        SweepBySid(sid);

        //-- Layer 3: 물리적 소멸 최종 확인
        if(VerifyPhysicalAbsence(sid)) {
            XP_LOG_OK(xp, StringFormat("[EXIT-SUCCESS] All assets cleared for SID: %s", sid));
            return true;
        }

        XP_LOG_WARN(xp, StringFormat("[EXIT-STILL-ACTIVE] Assets remaining for SID: %s. Will retry.", sid));
        return false;
    }

private:
    /**
     * @brief Layer 1: 티켓 기반 정밀 청산
     */
    void CloseByTicket(CXSignal* sig) {
        if(sig.ticket <= 0) return;

        if(PositionSelectByTicket((ulong)sig.ticket)) {
            m_trade.PositionClose((ulong)sig.ticket);
        }
        else if(OrderSelect((ulong)sig.ticket)) {
            m_trade.OrderDelete((ulong)sig.ticket);
        }
    }

    /**
     * @brief Layer 2: SID 기반 강제 소멸 (Fallback Sweep)
     */
    void SweepBySid(string sid) {
        //-- 포지션 스윕
        for(int i = PositionsTotal() - 1; i >= 0; i--) {
            ulong t = PositionGetTicket(i);
            if(PositionSelectByTicket(t) && PositionGetString(POSITION_COMMENT) == sid) {
                m_trade.PositionClose(t);
            }
        }
        //-- 주문 스윕
        for(int i = OrdersTotal() - 1; i >= 0; i--) {
            ulong t = OrderGetTicket(i);
            if(OrderSelect(t) && OrderGetString(ORDER_COMMENT) == sid) {
                m_trade.OrderDelete(t);
            }
        }
    }

    /**
     * @brief Layer 3: 터미널 존재 여부 확인 (SSOT Check)
     */
    bool VerifyPhysicalAbsence(string sid) {
        for(int i = 0; i < PositionsTotal(); i++) {
            if(PositionSelectByTicket(PositionGetTicket(i)) && PositionGetString(POSITION_COMMENT) == sid) return false;
        }
        for(int i = 0; i < OrdersTotal(); i++) {
            if(OrderSelect(OrderGetTicket(i)) && OrderGetString(ORDER_COMMENT) == sid) return false;
        }
        return true;
    }

public:
    void Reset() { m_magic = 0; }
};

#endif

#ifndef CXSIGNALWATCHER_MQH
#define CXSIGNALWATCHER_MQH

#include "..\Interfaces\IRepository.mqh"
#include "..\Interfaces\ICXConfig.mqh"
#include "..\Interfaces\ICXParam.mqh"
#include "..\Interfaces\ICXFluentSequence.mqh"
#include "..\Interfaces\CXMacros.mqh"
#include "..\Module\CXLogDispatcher.mqh"
#include "..\Infra\CXFileLogger.mqh"
#include "..\Infra\CXFluentSequence.mqh"
#include "..\Models\CXContext.mqh"

#include "Steps\Watcher\CXStepDiscovery.mqh"
#include "Steps\Watcher\CXStepValidation.mqh"
#include "Steps\Watcher\CXStepBinding.mqh"

/**
 * @class CXSignalWatcher
 * @brief 신규 신호 감시 시퀀스 통합 관리 담당
 */
class CXSignalWatcher {
private:
    IRepository*        m_repo;
    ICXConfig*          m_config;
    ICXContext*         m_ctx;
    ICXFluentSequence*  m_sequence;
    CXLogDispatcher*    m_logger; // 멀티 채널 로거

public:
    CXSignalWatcher(IRepository* repo, ICXConfig* config) 
        : m_repo(repo), m_config(config) {

        m_ctx = new CXContext();
        if(IS_VALID(m_ctx)) {
            m_ctx.Set("repo", m_repo);
            m_ctx.Set("config", m_config);
        }

        m_logger = new CXLogDispatcher();
        if(IS_VALID(m_logger)) {
            // Watcher 전용 로그 파일 초기화
            CXFileLogger* fileLog = new CXFileLogger();
            if(IS_VALID(fileLog)) {
                fileLog.Init("SignalWatcher");
                m_logger.SetFileLogger(fileLog);
            }
            m_ctx.Set("logger", m_logger);
        }

        m_sequence = new CXFluentSequence(m_ctx, "WatcherSeq");
        InitSequence();

        if(IS_VALID(m_logger)) m_logger.Dispatch(LOG_LVL_INFO, ">>> Signal Watcher Started <<<");
    }

    ~CXSignalWatcher() {
        SAFE_DELETE(m_sequence);
        SAFE_DELETE(m_logger);
        SAFE_DELETE(m_ctx);
    }

    /**
     * @brief 주기적 신호 감시 시퀀스 구동
     */
    void Pulse(ICXParam* xp) {
        if(IS_VALID(m_sequence)) {
            m_sequence.Pulse(xp);
        }
    }

private:
    void InitSequence() {
        CXFluentSequence* seq = dynamic_cast<CXFluentSequence*>(m_sequence);
        if(IS_INVALID(seq)) return;

        //-- Watcher 시퀀스 정의: Discovery -> Validation -> Binding
        seq.From(0).Execute(new CXStepDiscovery()).OnSuccess(1);
        seq.From(1).Execute(new CXStepValidation()).OnSuccess(2).OnFail(0);
        seq.From(2).Execute(new CXStepBinding()).OnSuccess(0);

        seq.Build();
    }
};

#endif

