public:
    CXExitManager(ICXContext* ctx) : m_ctx(ctx), m_magic(0) {}
    ~CXExitManager() {}

    void SetMagic(ulong magic) { m_magic = magic; m_trade.SetExpertMagicNumber(magic); }

    /**
     * @brief Layer 1: 티켓 기반 정밀 청산
     */
    void CloseByTicket(CXSignal* sig) {
        if(sig.ticket <= 0) return;

        if(PositionSelectByTicket((ulong)sig.ticket)) {
            m_trade.PositionClose((ulong)sig.ticket);
        }
        else if(OrderSelect((ulong)sig.ticket)) {
            m_trade.OrderDelete((ulong)sig.ticket);
        }
    }

    /**
     * @brief Layer 2: SID 기반 강제 소멸 (Fallback Sweep)
     */
    void SweepBySid(string sid) {
        //-- 포지션 스윕
        for(int i = PositionsTotal() - 1; i >= 0; i--) {
            ulong t = PositionGetTicket(i);
            if(PositionSelectByTicket(t) && PositionGetString(POSITION_COMMENT) == sid) {
                m_trade.PositionClose(t);
            }
        }
        //-- 주문 스윕
        for(int i = OrdersTotal() - 1; i >= 0; i--) {
            ulong t = OrderGetTicket(i);
            if(OrderSelect(t) && OrderGetString(ORDER_COMMENT) == sid) {
                m_trade.OrderDelete(t);
            }
        }
    }

    /**
     * @brief Layer 3: 터미널 존재 여부 확인 (SSOT Check)
     */
    bool VerifyPhysicalAbsence(string sid) {
        for(int i = 0; i < PositionsTotal(); i++) {
            if(PositionSelectByTicket(PositionGetTicket(i)) && PositionGetString(POSITION_COMMENT) == sid) return false;
        }
        for(int i = 0; i < OrdersTotal(); i++) {
            if(OrderSelect(OrderGetTicket(i)) && OrderGetString(ORDER_COMMENT) == sid) return false;
        }
        return true;
    }

public:
    void Reset() { m_magic = 0; }
};

#endif

