#ifndef CXSTEPENTRYTRAILING_MQH
#define CXSTEPENTRYTRAILING_MQH

#include "..\..\..\Interfaces\IXStep.mqh"
#include "..\..\..\Interfaces\IXTrailingStrategy.mqh"
#include "..\..\Execution\CXOrderManager.mqh"
#include "..\..\Execution\CXEntryManager.mqh"

/**
 * @class CXStepEntryTrailing
 * @brief 지정가 주문의 실시간 가격 추적 및 수정을 담당하는 원자적 단계
 */
class CXStepEntryTrailing : public IXStep {
private:
    string m_name;

public:
    CXStepEntryTrailing() : m_name("Step_EntryTrailing") {}
    virtual ~CXStepEntryTrailing() {}

    virtual string Name() override { return m_name; }

    /**
     * @brief 트레일링 실행 조건 확인 (주문이 배치된 대기 상태)
     */
    virtual bool OnCondition(ICXParam* xp, ICXContext* ctx, int current_state) override {
        ICXSignal* sig = xp.GetSignal();
        if(IS_INVALID(sig)) return false;

        CXSignal* signal = dynamic_cast<CXSignal*>(sig);
        // spec.md: Entry Activation (xa_entry > 0 AND xe_status < 10)
        // XE_PENDING_PLACED(1) 상태에서 활성화
        return (signal.xa_entry > 0 && signal.xe_status == XE_PENDING_PLACED);
    }

    /**
     * @brief 트레일링 로직 실행
     */
    virtual int OnProcess(ICXParam* xp, ICXContext* ctx) override {
        // 1. 전략 및 매니저 획득
        IXTrailingStrategy* strategy = (IXTrailingStrategy*)ctx.Get("entry_strategy");
        CXOrderManager*     orderMgr = (CXOrderManager*)ctx.Get("order_mgr");
        CXSignal*           sig      = dynamic_cast<CXSignal*>(xp.GetSignal());

        if(IS_INVALID(strategy) || IS_INVALID(orderMgr) || IS_INVALID(sig)) return -1;

        // 2. 새로운 트레일링 가격 계산
        double newPrice = strategy.Calculate(xp, ctx);

        // 3. 임계치 도달 시 주문 수정 실행
        if(newPrice > 0 && newPrice != sig.price_signal) {
            if(orderMgr.ModifyOrder((ulong)sig.ticket, newPrice, sig.sl, sig.tp)) {
                XP_LOG_INFO(xp, StringFormat("[TE-MODIFY] Ticket:%lld, Price:%.5f -> %.5f", sig.ticket, sig.price_signal, newPrice));
                sig.price_signal = newPrice;
                // 리포지토리 상태 업데이트는 필요시 수행
            }
        }

        // 4. 체결 여부 확인 (OnTradeTransaction에서 xe_status가 10으로 변경됨을 가정)
        if(sig.xe_status >= XE_EXECUTED) {
            return SESSION_ACTIVE;
        }

        return -1; // 현재 상태 유지
    }

    virtual void OnEnter(ICXContext* ctx) override {
        XP_LOG_INFO(NULL, "[STEP-TE] Starting Entry Trailing Loop");
    }

    virtual void OnExit(ICXContext* ctx) override {
        XP_LOG_INFO(NULL, "[STEP-TE] Exiting Entry Trailing Loop");
    }
};

#endif

