#ifndef CXSTEPEXITTRAILING_MQH
#define CXSTEPEXITTRAILING_MQH

#include "..\..\..\Interfaces\IXStep.mqh"
#include "..\..\..\Interfaces\IXTrailingStrategy.mqh"
#include "..\..\Execution\CXPositionManager.mqh"
#include "..\..\..\Models\CXSignal.mqh"

/**
 * @class CXStepExitTrailing
 * @brief 체결된 포지션의 수익 보존을 위한 익절 트레일링(Ik-Te) 담당 단계
 */
class CXStepExitTrailing : public IXStep {
private:
    string m_name;

public:
    CXStepExitTrailing() : m_name("Step_ExitTrailing") {}
    virtual ~CXStepExitTrailing() {}

    virtual string Name() override { return m_name; }

    /**
     * @brief 트레일링 실행 조건 확인 (포지션이 활성화된 상태)
     */
    virtual bool OnCondition(ICXParam* xp, ICXContext* ctx, int current_state) override {
        ICXSignal* sig = xp.GetSignal();
        if(IS_INVALID(sig)) return false;

        CXSignal* signal = dynamic_cast<CXSignal*>(sig);
        // 체결된 상태(10) 이상이고 아직 종료되지 않은 상태
        return (signal.xe_status >= 10 && signal.xe_status < 20);
    }

    /**
     * @brief 익절 트레일링 로직 실행
     */
    virtual int OnProcess(ICXParam* xp, ICXContext* ctx) override {
        // 1. 전략 및 매니저 획득
        IXTrailingStrategy* strategy = (IXTrailingStrategy*)ctx.Get("exit_strategy");
        CXPositionManager*  posMgr   = (CXPositionManager*)ctx.Get("pos_mgr");
        CXSignal*           sig      = dynamic_cast<CXSignal*>(xp.GetSignal());

        if(IS_INVALID(strategy) || IS_INVALID(posMgr) || IS_INVALID(sig)) return -1;

        // 2. 새로운 트레일링 SL 가격 계산
        double newSL = strategy.Calculate(xp, ctx);

        // 3. 수익 방향으로 SL 이동이 필요할 경우 실행
        if(newSL > 0 && newSL != sig.sl) {
            if(posMgr.ModifyPosition((ulong)sig.ticket, newSL, sig.tp)) {
                XP_LOG_INFO(xp, StringFormat("[IKTE-MODIFY] Ticket:%lld, SL:%.5f -> %.5f", sig.ticket, sig.sl, newSL));
                sig.sl = newSL;
            }
        }

        // 4. 외부 청산 신호(xa_exit) 발생 시 청산 단계로 즉시 전이
        if(sig.xa_exit > 0) {
            return SESSION_LIQUIDATING;
        }

        return -1; // 현재 상태 유지
    }

    virtual void OnEnter(ICXContext* ctx) override {
        XP_LOG_INFO(NULL, "[STEP-IKTE] Starting Exit Trailing (Profit Protection)");
    }

    virtual void OnExit(ICXContext* ctx) override {
        XP_LOG_INFO(NULL, "[STEP-IKTE] Stopping Exit Trailing");
    }
};

#endif

