/**
 * @brief 트레일링 계산 (진트/익트 공용)
 */
virtual double Calculate(ICXParam* xp, ICXContext* ctx) override {
    CXSignal* sig = dynamic_cast<CXSignal*>(xp.GetSignal());
    if(IS_INVALID(sig) || IS_INVALID(m_tracker)) return 0;

    ICXLogger* logger = (ICXLogger*)ctx.Get("logger");
    double point = SymbolInfoDouble(sig.symbol, SYMBOL_POINT);
    double currentPrice = SymbolInfoDouble(sig.symbol, (sig.dir == CX_DIR_BUY) ? SYMBOL_BID : SYMBOL_ASK);
    m_tracker.Update(currentPrice);

    double target = 0;

    //--- Case A: 진입 트레일링 (Entry Trailing)
    if(sig.xe_status == XE_PENDING_PLACED && sig.te_start > 0) {
        if(sig.dir == CX_DIR_BUY) {
            // Buy: 가격이 내려가면 진입가도 따라 내려감 (더 낮은 가격 추적)
            target = currentPrice - sig.te_start * point;
            if(target < sig.price_signal - sig.te_step * point) {
                m_targetPrice = NormalizeDouble(target, (int)SymbolInfoInteger(sig.symbol, SYMBOL_DIGITS));
            }
        }
        else if(sig.dir == CX_DIR_SELL) {
            // Sell: 가격이 올라가면 진입가도 따라 올라감 (더 높은 가격 추적)
            target = currentPrice + sig.te_start * point;
            if(target > sig.price_signal + sig.te_step * point) {
                m_targetPrice = NormalizeDouble(target, (int)SymbolInfoInteger(sig.symbol, SYMBOL_DIGITS));
            }
        }
    }
    //--- Case B: 익절 트레일링 (Exit Trailing / TS)
    else if(sig.xe_status >= XE_EXECUTED && sig.ts_start > 0) {
        double highest = m_tracker.GetHighest();
        double lowest  = m_tracker.GetLowest();

        if(sig.dir == CX_DIR_BUY) {
            double profit = currentPrice - sig.price_open;
            if(profit >= sig.ts_start * point) {
                target = highest - sig.ts_start * point; // 고점 대비 일정 거리 유지
                if(target > sig.sl + sig.ts_step * point) {
                    m_targetPrice = NormalizeDouble(target, (int)SymbolInfoInteger(sig.symbol, SYMBOL_DIGITS));
                }
            }
        }
        else if(sig.dir == CX_DIR_SELL) {
            double profit = sig.price_open - currentPrice;
            if(profit >= sig.ts_start * point) {
                target = lowest + sig.ts_start * point;
                if(target < sig.sl - sig.ts_step * point || sig.sl == 0) {
                    m_targetPrice = NormalizeDouble(target, (int)SymbolInfoInteger(sig.symbol, SYMBOL_DIGITS));
                }
            }
        }
    }

    if(m_targetPrice > 0 && IS_VALID(logger)) {
        logger.Log(LOG_LVL_TRACE, StringFormat("[%s] Recalculated Target: %.5f (Current: %.5f)", m_name, m_targetPrice, currentPrice));
    }

    return m_targetPrice; 
}

