/**
 * @class CXTradingSession
 * @brief 독립적인 샌드박스 실행 단위
 */
class CXTradingSession : public CObject {
private:
    ICXContext*         m_ctx;
    IRepository*        m_repo;
    CXLogDispatcher*    m_logger; // 멀티 채널 로거

    CXEntryManager*    m_entryMgr;
    CXOrderManager*    m_orderMgr;
    CXPositionManager* m_posMgr;
    CXExitManager*     m_exitMgr;
    ICXFluentSequence* m_sequence;

    bool               m_isActive;

public:
    CXTradingSession(IRepository* repo, ICXContext* globalCtx) 
        : m_repo(repo), m_isActive(false) {

        m_ctx = new CXContext();
        if(IS_INVALID(m_ctx)) return;

        m_logger = new CXLogDispatcher();
        if(IS_INVALID(m_logger)) return;

        // 글로벌 자원 및 세션 전용 자원 설정
        m_ctx.Set("repo", m_repo);
        m_ctx.Set("logger", m_logger);

        m_entryMgr = new CXEntryManager(m_ctx);
        if(IS_INVALID(m_entryMgr)) return;
        m_ctx.Set("entry_mgr", m_entryMgr);

        //-- 진입 트레일링 전략 등록
        CXTrailingFixed* entryTrl = new CXTrailingFixed("EntryFixed");
        if(IS_VALID(entryTrl)) m_ctx.Set("entry_strategy", entryTrl);

        m_orderMgr = new CXOrderManager(m_ctx);
        if(IS_INVALID(m_orderMgr)) return;
        m_ctx.Set("order_mgr", m_orderMgr);

        m_posMgr   = new CXPositionManager(m_ctx);
        if(IS_INVALID(m_posMgr)) return;
        m_ctx.Set("pos_mgr", m_posMgr);

        m_exitMgr  = new CXExitManager(m_ctx);
        if(IS_INVALID(m_exitMgr)) return;
        m_ctx.Set("exit_mgr", m_exitMgr);

        m_sequence = new CXFluentSequence(m_ctx, "SessionSeq");
        if(IS_INVALID(m_sequence)) return;

        InitSequence();
    }

    ~CXTradingSession() {
        SAFE_DELETE(m_entryMgr);
        SAFE_DELETE(m_orderMgr);
        SAFE_DELETE(m_posMgr);
        SAFE_DELETE(m_exitMgr);
        SAFE_DELETE(m_sequence);
        SAFE_DELETE(m_logger);
        SAFE_DELETE(m_ctx);
    }

    /**
     * @brief 신호와 함께 세션 가동 (로거 초기화 포함)
     */
    void Start(ICXParam* xp) {
        m_isActive = true;

        // 1. 파일 로거 초기화 (SID 기반 파일 생성)
        CXFileLogger* fileLog = new CXFileLogger();
        if(IS_VALID(fileLog)) {
            fileLog.Init(xp.GetString()); // xp 내부 SID 사용
            m_logger.SetFileLogger(fileLog);
        }

        m_logger.Log(LOG_LVL_OK, ">>> Trading Session Started <<<");
    }

    /**
     * @brief 매 틱 주기적 업데이트
     */
    void Pulse(ICXParam* xp) {
        if(!m_isActive) return;
        m_sequence.Pulse(xp);
    }

    /**
     * @brief 터미널 자산 정보를 기반으로 세션 상태 강제 복구 (Reverse Injection)
     */
    void InjectState(CXSignal* sig) {
        if(IS_INVALID(sig)) return;
        m_isActive = true;

        // 1. 시퀀스 상태 강제 전이 (Force Jump)
        if(sig.xe_status >= XE_EXECUTED) {
            m_sequence.ForceState(SESSION_ACTIVE);
            XP_LOG_OK(NULL, StringFormat("[INJECT] SID:%s - Recovered to ACTIVE state.", sig.sid));
        }
        else if(sig.xe_status == XE_PENDING_PLACED) {
            m_sequence.ForceState(1); // STATE_ENTRY_TRAILING
            XP_LOG_OK(NULL, StringFormat("[INJECT] SID:%s - Recovered to ENTRY_TRAILING state.", sig.sid));
        }

        // 2. 전략 및 추적기 초기화 (현재가 기준)
        // m_posMgr.Sync(sig); 
    }


    bool IsActive() const { return m_isActive; }

private:
    void InitSequence() {
        CXFluentSequence* seq = dynamic_cast<CXFluentSequence*>(m_sequence);
        if(IS_INVALID(seq)) return;

        //-- 1. 진입 단계 등록
        seq.From(SESSION_READY)
           .Execute(new CXStepEntry())
           .OnSuccess(1) // STATE_ENTRY_TRAILING
           .OnFail(SESSION_ERROR);

        seq.From(1) // STATE_ENTRY_TRAILING
           .Execute(new CXStepEntryTrailing())
           .OnSuccess(SESSION_ACTIVE)
           .OnFail(SESSION_ERROR);

        //-- 2. 모니터링 및 익절 트레일링 단계 등록
        seq.From(SESSION_ACTIVE)
           .Execute(new CXStepMonitor())
           .Case(SESSION_LIQUIDATING, SESSION_LIQUIDATING)
           .OnSuccess(2) // STATE_EXIT_TRAILING
           .OnFail(SESSION_ERROR);

        seq.From(2) // STATE_EXIT_TRAILING
           .Execute(new CXStepExitTrailing())
           .Case(SESSION_LIQUIDATING, SESSION_LIQUIDATING)
           .OnFail(SESSION_ERROR);

        //-- 3. 청산 단계 등록
        seq.From(SESSION_LIQUIDATING)
           .Execute(new CXStepExit())
           .OnSuccess(SESSION_CLOSED)
           .OnFail(SESSION_ERROR);

        seq.Build();
    }
};

#endif
    }
};

