 */
class CXStepExitTrailingCalc : public IXStep {
public:
    virtual string Name() override { return "Step_ExitTrailingCalc"; }

    virtual bool OnCondition(ICXParam* xp, ICXContext* ctx, int current_state) override {
        CXSignal* sig = dynamic_cast<CXSignal*>(xp.GetSignal());
        return (IS_VALID(sig) && sig.xe_status >= XE_EXECUTED && sig.ts_start > 0);
    }

    virtual int OnProcess(ICXParam* xp, ICXContext* ctx) override {
        CXSignal* sig = dynamic_cast<CXSignal*>(xp.GetSignal());
        IXPriceTracker* tracker = (IXPriceTracker*)ctx.Get("price_tracker");
        if(IS_INVALID(sig) || IS_INVALID(tracker)) return -1;

        double point = SymbolInfoDouble(sig.symbol, SYMBOL_POINT);
        double currentPrice = SymbolInfoDouble(sig.symbol, (sig.dir == CX_DIR_BUY) ? SYMBOL_BID : SYMBOL_ASK);
        tracker.Update(currentPrice);

        double highest = tracker.GetHighest();
        double lowest  = tracker.GetLowest();
        double target = 0;

        if(sig.dir == CX_DIR_BUY) {
            double profit = currentPrice - sig.price_open;
            if(profit >= sig.ts_start * point) {
                target = highest - sig.ts_start * point;
                if(target > sig.sl + sig.ts_step * point) {
                    sig.sl = NormalizeDouble(target, (int)SymbolInfoInteger(sig.symbol, SYMBOL_DIGITS));
                    return 1; // MODIFIED
                }
            }
        }
        else if(sig.dir == CX_DIR_SELL) {
            double profit = sig.price_open - currentPrice;
            if(profit >= sig.ts_start * point) {
                target = lowest + sig.ts_start * point;
                if(target < sig.sl - sig.ts_step * point || sig.sl == 0) {
                    sig.sl = NormalizeDouble(target, (int)SymbolInfoInteger(sig.symbol, SYMBOL_DIGITS));
                    return 1; // MODIFIED
                }
            }
        }

        return 0; // NO_CHANGE
    }

    virtual void OnEnter(ICXContext* ctx) override {}
    virtual void OnExit(ICXContext* ctx) override {}
};

